// New Game starting notes for the Mad City (generated from the GM's 'Mad City Locations.zip').
window.DRYH_MADCITY_SEED = {"nodes":[{"id":"breakers-yard","name":"Breaker's Yard","subs":[{"id":"breakers-yard-0","name":"Metro Car","items":[{"id":"breakers-yard-1","kind":"interact","text":"Arriving.","sub":"The car jolts and brakes to a stop. The lights stutter, the doors hiss open.","acts":[1],"diff":4},{"id":"breakers-yard-2","kind":"see","text":"Stopped carriage","sub":"A single Tube car, about 15 meters long, lit by flickering strip lights. The doors on both sides stand open. The only thing to be found is a loose boot.","acts":[1,2,3],"diff":4},{"id":"breakers-yard-3","kind":"see","text":"Dark carriage.","sub":"The strip lights are out. Only the emergency lights glow a dull red.","acts":[3],"diff":4},{"id":"breakers-yard-4","kind":"object","text":"Boot","sub":"Brown, and without its other half. Worn.","acts":[1,2,3],"diff":4},{"id":"breakers-yard-5","kind":"see","text":"Driver’s cab","sub":"Locked, with the blind pulled down.","acts":[1,2,3],"diff":4},{"id":"breakers-yard-6","kind":"danger","text":"Pry the cab door","sub":"With an object. Harder with bare hands, easier with a fitting item.","acts":[1,2,3],"diff":4},{"id":"breakers-yard-7","kind":"see","text":"Cab radio","sub":"A handset on a curly cord, with a red TALK button.","acts":[1,2,3],"diff":4},{"id":"breakers-yard-8","kind":"talk","text":"The Turncock (Radio)","sub":"He’s tired, grumpy and talks like a London bus controller.","acts":[1,2,3],"diff":4,"subjects":[{"id":"breakers-yard-9","name":"Stopped?","info":"Fatberg comes out during the 13th hour. We stop all cars to avoid damage to the line. Non-negotiable. Nothing moves while that thing’s on my line. I’m not risking the rolling stock."},{"id":"breakers-yard-a","name":"Fatberg","info":"Some fast bastard made of grease and junk. Eats anything. Last time it came upon a metro car, it ate it whole."},{"id":"breakers-yard-b","name":"Breakers","info":"I think they work for the Wax King, or maybe they just like shredding junk. They grind objects into spirits and the King mints it at the Wax Works. Although they have thrown people in there. They shred anything the Foreman marks with a red X."},{"id":"breakers-yard-c","name":"Walk the line?","info":"Never walk on the line, it's dangerous, especially at this time. Loco Motto likes to roam around for lost souls."}]},{"id":"breakers-yard-d","kind":"see","text":"Through the windows","sub":"A huge yard of scrap stretching in every direction, much wider than the car, with figures moving in the distance.","acts":[1,2,3],"diff":4},{"id":"breakers-yard-e","kind":"interact","text":"Line reopens","sub":"(After Fatberg is shredded.) The intercom crackles: “Main Line is now running. Mind the gap.” The doors close, and the car can carry onward.","acts":[1,2,3],"diff":4}],"desc":"An empty Tube carriage, stopped dead, under strip lights that buzz and stutter. The air is stale and warm, and smells of old seats and brake dust."},{"id":"breakers-yard-f","name":"Scrap Field","items":[{"id":"breakers-yard-g","kind":"see","text":"Scrap","sub":"Mounds of rusted metal, broken furniture, prams and old televisions, stretching about 100 meters in every direction.","acts":[1,2,3],"diff":4},{"id":"breakers-yard-h","kind":"interact","text":"Empty yard.","sub":"No Snuffers, no Breakers, no one shuffling to the Turnstiles. Nothing moves.","acts":[3],"diff":4},{"id":"breakers-yard-i","kind":"danger","text":"Cross the yard.","sub":"Every move between sub-locations, guarded or not. On a failure, Fatberg erupts from the scrap.","acts":[3],"diff":6},{"id":"breakers-yard-j","kind":"object","text":"Scrap","sub":"An armful of scrap; broken wood, twisted metal and mucky dirt.","acts":[1,2,3],"diff":4},{"id":"breakers-yard-k","kind":"see","text":"Shopping trolley","sub":"Half-buried in scrap, tipped on its side, with one wheel bent. If freed, it can carry three loads of junk.","acts":[1,2,3],"diff":4},{"id":"breakers-yard-l","kind":"danger","text":"Dig out the trolley.","sub":"Free with an item.","acts":[1,2,3],"diff":2},{"id":"breakers-yard-m","kind":"object","text":"Shopping trolley","sub":"A rattling steel trolley. It squeaks loudly when pushed.","acts":[1,2,3],"diff":4},{"id":"breakers-yard-n","kind":"see","text":"Body","sub":"A man lies face-down near the turnstiles, in a torn suit, not moving.","acts":[1],"diff":4},{"id":"breakers-yard-o","kind":"see","text":"Wrecked Carriage","sub":"Off to the right, an old train car on its side, burning low.","acts":[1,2,3],"diff":4},{"id":"breakers-yard-p","kind":"see","text":"Snuffers","sub":"Two tall, stooped figures in long black coats, with brass cones where their heads should be. One stands off toward the Turnstiles, and one toward the Wrecked Carriage.","acts":[1,2,3],"diff":4},{"id":"breakers-yard-q","kind":"interact","text":"The snuffing","sub":"The body stirs and pushes itself up. A Snuffer is on it in seconds, pressing a gray paste over the man’s face. He screams and thrashes for a long time, then goes limp. When he stands, his face is smooth wax, with a black wick on his crown. He walks off toward the Turnstiles.","acts":[1],"diff":4},{"id":"breakers-yard-r","kind":"see","text":"Breakers","sub":"Rat-sized critters, about 30 centimeters tall, with gray hairless skin and oversized hands. They wear tiny dented hard hats and cracked goggles, and they chatter in high, quick voices. They work in chains, passing scrap from hand to hand, and they tear metal apart with their bare fingers as if it were bread.","acts":[1,2,3],"diff":4},{"id":"breakers-yard-s","kind":"see","text":"Metro Car","sub":"The stopped carriage, lit from inside, doors open.","acts":[1,2,3],"diff":4},{"id":"breakers-yard-t","kind":"see","text":"Junk Heap","sub":"Behind the car, a mountain of shredded scrap, with Breakers crawling over it.","acts":[1,2,3],"diff":4},{"id":"breakers-yard-u","kind":"see","text":"Turnstiles","sub":"Off to the left, a row of rusted barriers.","acts":[1,2,3],"diff":4}],"desc":"A vast junkyard under a low, dark ceiling, with scrap piled as far as the light goes. The air smells of rust, damp and old oil, and grit crunches underfoot."},{"id":"breakers-yard-v","name":"Turnstiles","items":[{"id":"breakers-yard-w","kind":"see","text":"Turnstiles","sub":"A row of six rusted barriers, worn smooth by passing hands, at the mouth of a tunnel that glows orange in the distance.","acts":[1,2,3],"diff":4},{"id":"breakers-yard-x","kind":"object","text":"Bucket","sub":"A dented tin bucket, about 10 liters, with a wire handle.","acts":[1,2,3],"diff":4},{"id":"breakers-yard-y","kind":"see","text":"Snuffer","sub":"A tall, stooped figure in a long black coat, with a brass cone where its head should be.","acts":[1,2,3],"diff":4},{"id":"breakers-yard-z","kind":"danger","text":"Sneak past the Snuffer.","sub":"On a pass, it moves to its other bridge.","acts":[1,2,3],"diff":4},{"id":"breakers-yard-10","kind":"danger","text":"Pass as Smothered.","sub":"Once. Check again if you cause a scene.","acts":[1,2,3],"diff":4},{"id":"breakers-yard-11","kind":"see","text":"Wax puddle","sub":"A hardened pool of off-white wax under the barriers, where the body was.","acts":[1,2,3],"diff":4},{"id":"breakers-yard-12","kind":"see","text":"Exit","sub":"Beyond the barriers, a sloping tunnel, warm and orange, with the smell of hot wax drifting up.","acts":[1,2,3],"diff":4}],"desc":"A row of rusted barriers at the mouth of a warm, glowing tunnel. The air is heavy with the smell of hot wax and smoke."},{"id":"breakers-yard-13","name":"Exit","items":[{"id":"breakers-yard-14","kind":"danger","text":"Sneak past the Snuffer.","sub":"On a pass, it moves to its other bridge.","acts":[1,2,3],"diff":4},{"id":"breakers-yard-15","kind":"danger","text":"Pass as Smothered.","sub":"Once. Check again if you cause a scene.","acts":[1,2,3],"diff":4}],"desc":"Open route travelled by Snuffers, leads to Wax Works."},{"id":"breakers-yard-16","name":"Wreck","items":[{"id":"breakers-yard-17","kind":"see","text":"Burning wreck","sub":"An old Tube carriage on its side, about 15 meters long, half buried in scrap and burning low. The heat can be felt from a few meters away.","acts":[1,2,3],"diff":4},{"id":"breakers-yard-18","kind":"interact","text":"Hot fire","sub":"The wreck is burning, and can be used as a furnace. This can melt the wax.","acts":[1,2,3],"diff":4},{"id":"breakers-yard-19","kind":"interact","text":"Cold wreck.","sub":"The fire is out. The carriage is crushed flat, as if something rolled over it.","acts":[3],"diff":4},{"id":"breakers-yard-1a","kind":"danger","text":"Wax yourself.","sub":"(2, Simple) with grease, (6, Dangerous) without.","acts":[1,2,3],"diff":6},{"id":"breakers-yard-1b","kind":"see","text":"The Foreman","sub":"A Breaker twice the size of the others, about 60 centimeters tall, in a white hard hat. He paints red X’s on the wreck with a brush.","acts":[1,2,3],"diff":4},{"id":"breakers-yard-1c","kind":"interact","text":"Bothering the Foreman","sub":"The Foreman pays no attention to anyone who leaves him alone. Talking to him, blocking him or touching his stuff makes him whistle for the Snuffer.","acts":[1,2,3],"diff":4},{"id":"breakers-yard-1d","kind":"see","text":"Paint pot","sub":"A tin of red paint at the Foreman’s feet, with a spare brush across the lid.","acts":[1,2,3],"diff":4},{"id":"breakers-yard-1e","kind":"danger","text":"Steal the paint.","sub":"On a failure, the Foreman whistles, and the Snuffer comes straight here to search.","acts":[1,2,3],"diff":4},{"id":"breakers-yard-1f","kind":"object","text":"Red paint","sub":"A tin of thick red paint and a brush.","acts":[1,2,3],"diff":4},{"id":"breakers-yard-1g","kind":"see","text":"Breakers","sub":"A dozen of them, tearing at the marked panels with bare hands and passing the pieces back toward the Junk Heap in a chain.","acts":[1,2,3],"diff":4},{"id":"breakers-yard-1h","kind":"see","text":"Greasing up","sub":"Before climbing onto the hot metal, each Breaker dips its arms in a drum of gray grease.","acts":[1,2,3],"diff":4},{"id":"breakers-yard-1i","kind":"see","text":"Grease drum","sub":"A dented oil drum, full of thick gray grease.","acts":[1,2,3],"diff":4},{"id":"breakers-yard-1j","kind":"danger","text":"Take some grease.","sub":"On a failure, the Foreman whistles, and the Snuffer comes straight here to search.","acts":[1,2,3],"diff":4},{"id":"breakers-yard-1k","kind":"object","text":"Grease","sub":"A handful of thick gray grease that smells of drains and old chips. It keeps hot wax from sticking or burning.","acts":[1,2,3],"diff":4},{"id":"breakers-yard-1l","kind":"see","text":"Snuffer","sub":"A tall, stooped figure in a long black coat, with a brass cone where its head should be.","acts":[1,2,3],"diff":4},{"id":"breakers-yard-1m","kind":"danger","text":"Sneak past the Snuffer.","sub":"On a pass, it moves to its other bridge.","acts":[1,2,3],"diff":4},{"id":"breakers-yard-1n","kind":"danger","text":"Pass as Smothered.","sub":"Once. Check again if you cause a scene.","acts":[1,2,3],"diff":4},{"id":"breakers-yard-1o","kind":"see","text":"Metro Car","sub":"Back across the yard, the stopped carriage, lit from inside.","acts":[1,2,3],"diff":4},{"id":"breakers-yard-1p","kind":"see","text":"Tunnel mouth","sub":"Farther on, a dark tunnel.","acts":[1,2,3],"diff":4}],"desc":"A burning carriage on its side, throwing heat and orange light across the scrap. Smoke stings the eyes, and the air reeks of scorched metal and grease."},{"id":"breakers-yard-1q","name":"Fatberg's Tunnel","items":[{"id":"breakers-yard-1r","kind":"see","text":"Fatberg","sub":"A crocodile about 12 meters long, made of gray fat, grease, matted wipes, bottles and scrap, all glued together in a slick, sagging mass. Its jaws are lined with broken cutlery and bike spokes for teeth, and its small dark eyes sink in and resurface as it moves. It paces the tunnel back and forth, scraping both walls.","acts":[1,2,3],"diff":4},{"id":"breakers-yard-1s","kind":"see","text":"Grease heap","sub":"A mound of gray grease, about 3 meters high, at the tunnel mouth, where Fatberg squeezed itself through and left part of itself behind.","acts":[3],"diff":4},{"id":"breakers-yard-1t","kind":"danger","text":"Escape Fatberg.","sub":"While it can still move.","acts":[1,2,3],"diff":6},{"id":"breakers-yard-1u","kind":"interact","text":"Feeding","sub":"Fatberg swallows any junk thrown into its mouth. Each armful makes it swell. After three, it wedges in the tunnel and can’t move, though its jaws still snap.","acts":[1,2,3],"diff":4},{"id":"breakers-yard-1v","kind":"interact","text":"Tight fit","sub":"Its sides drag along the tiles, and it has to squeeze to turn.","acts":[1,2,3],"diff":4},{"id":"breakers-yard-1w","kind":"interact","text":"Morphing","sub":"Fatberg can’t be flanked. Come at it from behind, and its face slides through its body to the other end.","acts":[1,2,3],"diff":4},{"id":"breakers-yard-1x","kind":"danger","text":"Paint the X.","sub":"It’s stuck but still snapping, and the paint has to go on its body.","acts":[1,2,3],"diff":4},{"id":"breakers-yard-1y","kind":"interact","text":"Shredding.","sub":"(Once Fatberg is stuck and marked with a red X.) The Breakers pour in, swarm over it and tear it apart, carrying it off to the Junk Heap piece by piece. The line is clear.","acts":[1,2,3],"diff":4},{"id":"breakers-yard-1z","kind":"see","text":"Greasy tiles","sub":"The white tunnel tiles are thick with gray smears, where Fatberg rubs past.","acts":[1,2,3],"diff":4},{"id":"breakers-yard-20","kind":"object","text":"Grease","sub":"A handful of thick gray grease that smells of drains and old chips. It keeps hot wax from sticking or burning.","acts":[1,2,3],"diff":4},{"id":"breakers-yard-21","kind":"see","text":"Warning sign","sub":"An enamel sign bolted to the wall, dented as if hit at speed: “DANGER. DO NOT WALK ON THE LINE.\"","acts":[1,2,3],"diff":4},{"id":"breakers-yard-22","kind":"see","text":"The Main Line","sub":"Rails disappearing into the dark beyond Fatberg.","acts":[1,2,3],"diff":4},{"id":"breakers-yard-23","kind":"see","text":"Wreck","sub":"Back toward the yard, the burning carriage, throwing orange light into the tunnel mouth.","acts":[1,2,3],"diff":4},{"id":"breakers-yard-24","kind":"danger","text":"Sneak past the Snuffer.","sub":"On a pass, it moves to its other bridge.","acts":[1,2,3],"diff":4},{"id":"breakers-yard-25","kind":"danger","text":"Pass as Smothered.","sub":"Once. Check again if you cause a scene.","acts":[1,2,3],"diff":4}],"desc":"A tiled Tube tunnel, choked with the stench of rancid fat and sewage. Something enormous scrapes along the walls in the dark, wet and heavy. The air is warm and thick, and every surface is slick."},{"id":"breakers-yard-26","name":"Junk Heap","items":[{"id":"breakers-yard-27","kind":"see","text":"The heap","sub":"A mountain of shredded scrap behind the car, about 10 meters high, that shifts and settles with a constant rattle.","acts":[1,2,3],"diff":4},{"id":"breakers-yard-28","kind":"object","text":"Scrap","sub":"An armful of scrap; broken wood, twisted metal and mucky dirt.","acts":[1,2,3],"diff":4},{"id":"breakers-yard-29","kind":"danger","text":"Dig yourself out.","sub":"After a crash.","acts":[1,2,3],"diff":4},{"id":"breakers-yard-2a","kind":"see","text":"Breakers","sub":"Rat-sized critters in dented hard hats and cracked goggles, hauling scrap up the slope in chains and tossing it on top, chattering the whole time.","acts":[1,2,3],"diff":4},{"id":"breakers-yard-2b","kind":"see","text":"Metro Car","sub":"The back of the stopped carriage, lit from inside.","acts":[1,2,3],"diff":4}],"desc":"A towering slope of shredded scrap behind the car, always shifting and rattling. The air is thick with dust and the tang of rust, and the ground gives way underfoot."}],"boons":[{"id":"breakers-yard-2c","name":"Unclog the Line","note":"Defeating the Nightmare makes all stations available for navigation."}],"desc":"A vast junkyard at the dead end of the Main Line, buried under a low, dark ceiling. The air reeks of rust, smoke and rancid fat. Scrap creaks and settles.","nightmare":"Fatberg","crashDesc":"The Breakers will have marked them with a red X, and they will have to crawl out of the Heap. They will also have lost on item in the heap.","starts":["c4"],"x":40,"y":800},{"id":"district13","name":"District 13","subs":[{"id":"district13-0","name":"Roundabout","items":[{"id":"district13-1","kind":"see","text":"Ring road","sub":"A wide cobbled circle, lit by gas lamps at every few meters. The buildings all face inward.","acts":[1,2,3],"diff":4},{"id":"district13-2","kind":"see","text":"Empty plinth","sub":"A stone island in the middle, with four bolt holes and chain scars where something large once stood.","acts":[1,2,3],"diff":4},{"id":"district13-3","kind":"see","text":"Clockwork Lieutenants","sub":"Policemen in uniforms from all over the world, with frozen grins and a slowly turning key in each back. They direct traffic with white gloves and tip their caps to everyone who passes.","acts":[1,2,3],"diff":4},{"id":"district13-4","kind":"interact","text":"Breaking the law","sub":"An officer whistles and comes. A person's first infraction is a warning, but the second is an arrest, which leads to the Big House.","acts":[1,2,3],"diff":4},{"id":"district13-5","kind":"see","text":"Needle Noses","sub":"Bloodhounds with threaded needles for heads, sniffing along the curb, each trailing thread to an invisible spool.","acts":[1,2,3],"diff":4},{"id":"district13-6","kind":"see","text":"Pin Heads","sub":"Wiry men in rumpled 1940s suits, with straight pins for heads and fedoras hovering above them, scribbling in notebooks at every corner.","acts":[1,2,3],"diff":4},{"id":"district13-7","kind":"see","text":"Courthouse","sub":"A grand stone building with broad steps and a pillared front.","acts":[1,2,3],"diff":4},{"id":"district13-8","kind":"see","text":"Theater","sub":"The old hospital wing, red brick, with a gaudy marquee over the entrance.","acts":[1,2,3],"diff":4},{"id":"district13-9","kind":"see","text":"Collections Office","sub":"A narrow brick building with a brass plaque.","acts":[1,2,3],"diff":4},{"id":"district13-a","kind":"see","text":"Main Line entrance","sub":"A Tube station stairway, with an iron gate pulled across and a notice above: LINE CLOSED, OBSTRUCTION.","acts":[1,2,3],"diff":4},{"id":"district13-b","kind":"see","text":"Fire escape","sub":"A black iron ladder up the side of the Courthouse, vanishing into the roofline. Leads to the Rooftop Jungle.","acts":[1,2,3],"diff":4},{"id":"district13-c","kind":"see","text":"Gate","sub":"To the Warrens. Can leave for any reason, but to get in, one needs to be summoned or arrested.","acts":[1,2,3],"diff":4}],"desc":"A wide cobbled circle ringed by stern, tall buildings, all facing inward. Gas lamps hiss, and boots tap in perfect time."},{"id":"district13-d","name":"Courthouse","items":[{"id":"district13-e","kind":"see","text":"Steps","sub":"Broad stone steps under a sign: SUMMONSES RECEIVED HERE.","acts":[1,2,3],"diff":4},{"id":"district13-f","kind":"see","text":"Clerks’ counter","sub":"A long oak counter with a brass grille. Officer clerks stamp forms in rows.","acts":[1,2,3],"diff":4},{"id":"district13-g","kind":"see","text":"Public gallery","sub":"Rows of benches where locals sit in gray suits, clutching summonses and waiting.","acts":[1,2,3],"diff":4},{"id":"district13-h","kind":"see","text":"Tock’s door","sub":"A dark wood door marked CHIEF OF POLICE. Behind it, through a crack, a small brick prison sits on a table.","acts":[1,2,3],"diff":4},{"id":"district13-i","kind":"see","text":"Courtroom","sub":"An empty courtroom, with a jury box, a bench and a seat for the judge. Empty.","acts":[1,2,3],"diff":4},{"id":"district13-j","kind":"talk","text":"Judge Ormerod","sub":"Gruff, fussy and bored. He is only there during a subepeona.","acts":[1,2,3],"diff":4}],"desc":"A vast stone hall, hushed and cold, with a high ceiling lost in shadow. The air smells of floor polish, ink and damp wool. Stamps thump in a steady rhythm."},{"id":"district13-k","name":"Theater","items":[{"id":"district13-l","kind":"see","text":"Hospital wing","sub":"A red-brick building with tall arched windows, an ambulance bay, and a faded sign over a side door: WARD 13.","acts":[1,2,3],"diff":4},{"id":"district13-m","kind":"see","text":"Marquee","sub":"A gaudy new sign bolted to the old entrance: PROFESSOR CRANE’S GALVANIC MARVELS. NOW SHOWING. NO ADMITTANCE DURING PERFORMANCE.","acts":[1,2,3],"diff":4},{"id":"district13-n","kind":"see","text":"Chained doors","sub":"Frosted-glass double doors, chained and padlocked.","acts":[1,2,3],"diff":4},{"id":"district13-o","kind":"talk","text":"The Usher","sub":"A stiff man in a tight burgundy uniform, buttoned to the throat, standing just inside the frosted glass with his hands folded.","acts":[1,2,3],"diff":4,"subjects":[{"id":"district13-p","name":"Entry","info":"“Performance in progress. No admittance.”"}]},{"id":"district13-q","kind":"see","text":"Brass grille","sub":"A small speaking grille in the door, at head height, slid open when he talks.","acts":[1,2,3],"diff":4}],"desc":"A tall red-brick hospital wing, gaudy lights strung across its grim front. The air smells of disinfectant."},{"id":"district13-r","name":"Collections Office","items":[{"id":"district13-s","kind":"see","text":"Wall of trophies","sub":"A wall of pins, floor to ceiling, each pinning a tiny object: a ribbon, a photo corner, a ticking brass box, a glowing thread.","acts":[1,2,3],"diff":4},{"id":"district13-t","kind":"see","text":"Desk","sub":"A huge, immaculate desk, bare but for a rubber stamp, an ink pad and a single form.","acts":[1,2,3],"diff":4},{"id":"district13-u","kind":"talk","text":"The Tacks Man","sub":"A figure in a business suit that never wrinkles, with a plastic push-pin for a head and fingers that come to metal points.","acts":[1,2,3],"diff":4,"subjects":[{"id":"district13-v","name":"Deal","info":"He wants the guest book. Fenwick Quire keeps every name that has come through his door, and the Tacks Man would like it in his collection. His Pin Heads can’t touch the Revealer without a quarrel with the Paper Boys, and he won’t break the rules himself."},{"id":"district13-w","name":"Reward","info":"One law, properly drafted and stamped, enforced wherever Tock’s police go."},{"id":"district13-x","name":"Ribbon","info":"“A name. The letters are stitched into the band. The gentleman who owned it can no longer be summoned, addressed or recalled. A tidy arrangement.”"},{"id":"district13-y","name":"Photo","info":"“A moment. The last hour a woman spent with her husband, mounted for safekeeping. She remembers that he existed. She does not remember the hour.”"},{"id":"district13-z","name":"Brass box","info":"“A heart. It continues to run, as you can hear. The owner does not. I find the sound restful.”"},{"id":"district13-10","name":"Thread","info":"“A memory, drawn out in a single pull. It is a spirited specimen. The subject has a gap in his life, about the length of a summer. It used to be the best summer of his life.”"}]},{"id":"district13-11","kind":"see","text":"Pin Head clerks","sub":"Typing at small desks along the walls.","acts":[1,2,3],"diff":4},{"id":"district13-12","kind":"see","text":"Needle Nose","sub":"Asleep under the desk, its thread trailing off to an invisible spool.","acts":[1,2,3],"diff":4}],"desc":"A narrow, windowless office, quiet and spotless, lit by green-shaded lamps. The air smells of rubber stamps, ink and cold metal, and a typewriter clacks somewhere behind the walls.."}],"boons":[{"id":"district13-13","name":"New Law","note":""}],"desc":"A cold, grand square of law courts and ledgers, ringed by stern buildings. Officers in rigid uniforms stand at every corner, tipping their caps with a click. The air smells of coal smoke. and ushers in a cool breeze.","nightmare":"The Tacks Man","crashDesc":"Arrested and put in jail, or asked to subpoena in front of the course, and possibly fined.","favText":"New Law","x":40,"y":140},{"id":"howlers-realm","name":"Howler's Realm","subs":[{"id":"howlers-realm-0","name":"The Crucible","items":[]}],"boons":[{"id":"howlers-realm-1","name":"The Crucible","note":"Gaining respect from the Magnificent Howler allows access, and it can melt the Royal Seal."}],"nightmare":"The Red Dragon","x":440,"y":800},{"id":"rooftop","name":"Rooftop Jungle","subs":[{"id":"rooftop-0","name":"The Air Fort","items":[]}],"boons":[{"id":"rooftop-1","name":"Knife","note":"Can be stolen, taken, or given from the Roof Rats. Cuts literally anything."}],"nightmare":"Shredder","x":840,"y":140},{"id":"big-house","name":"The Big House","subs":[{"id":"big-house-0","name":"The Cell","items":[{"id":"big-house-1","kind":"interact","text":"Arriving","sub":"Alice, now small as a mouse, was just place inside her cell.","acts":[1],"diff":4},{"id":"big-house-2","kind":"see","text":"Cell","sub":"A bare brick cell, with a barred window to the tabletop and a heavy iron door on a simple latch.","acts":[1,2,3],"diff":4},{"id":"big-house-3","kind":"interact","text":"Cell door latch","sub":"It can be reached through the bars from inside, but only Alice's hands are small enough to fit through.","acts":[1,2,3],"diff":4},{"id":"big-house-4","kind":"see","text":"Iron cot","sub":"A narrow cot with a thin, gray mattress and a bare slat frame.","acts":[1,2,3],"diff":4},{"id":"big-house-5","kind":"object","text":"Bed slat","sub":"A thin pine slat.","acts":[1,2,3],"diff":4},{"id":"big-house-6","kind":"see","text":"Mealtime tray","sub":"A tin tray on the floor, with a dirty bowl and a bent tin spoon.","acts":[1,2,3],"diff":4},{"id":"big-house-7","kind":"object","text":"Tin spoon","sub":"A bent tin spoon.","acts":[1,2,3],"diff":4},{"id":"big-house-8","kind":"object","text":"Absalom’s blanket","sub":"A scratchy gray blanket.","acts":[1,2,3],"diff":4},{"id":"big-house-9","kind":"see","text":"Barred window","sub":"Bars as thick as her arm. Beyond them, the tabletop stretches like a field of polished wood.","acts":[1,2,3],"diff":4},{"id":"big-house-a","kind":"talk","text":"Absalom","sub":"A thin, pale man wrapped head to toe in prison blankets like a cocoon, with flaking skin on his arms. Slow, rude and sleepy.","acts":[1,2,3],"diff":4,"subjects":[{"id":"big-house-b","name":"Crime","info":"Arrested for staying out past the curfew bell. He has no home. He was told that was no excuse."}]},{"id":"big-house-c","kind":"danger","text":"Unlatch the cell door.","sub":"A sneaky action. Sneaky actions increase in difficulty cumulatively. A failure resets the difficulty, but sets +2 permanently (once).","acts":[1,2,3],"diff":2}],"desc":"A cramped brick cell, cold and damp, with a bare cot and a barred window."},{"id":"big-house-d","name":"The Other Cell","items":[{"id":"big-house-e","kind":"see","text":"Cell","sub":"A cell like the first, with a card table bolted to the wall, two cots and a cuckoo clock above the door.","acts":[1,2,3],"diff":4},{"id":"big-house-f","kind":"interact","text":"Cell door latch","sub":"Reached through the bars.","acts":[1,2,3],"diff":4},{"id":"big-house-g","kind":"see","text":"Cuckoo clock","sub":"A small wooden cuckoo clock at head height, with a pinecone weight, a painted bird in a door and a square winding socket under the face.","acts":[1,2,3],"diff":4},{"id":"big-house-h","kind":"see","text":"Tea hatch","sub":"A little iron hatch in the wall beside the clock, shut tight.","acts":[1,2,3],"diff":4},{"id":"big-house-i","kind":"object","text":"Scone","sub":"A warm, crumbly scone.","acts":[1,2,3],"diff":4},{"id":"big-house-j","kind":"object","text":"Pot of jam","sub":"A small pot of strawberry jam.","acts":[1,2,3],"diff":4},{"id":"big-house-k","kind":"interact","text":"Crank the clock","sub":"Wedge the spoon into the socket and turn. Each full turn is an hour. At four, the cuckoo calls and the tea hatch opens, and a clockwork arm pushes out a tray of scones, a pot of jam and tiny cups of tea.","acts":[1,2,3],"diff":4},{"id":"big-house-l","kind":"object","text":"Jack’s comb","sub":"A thin tortoiseshell comb.","acts":[1,2,3],"diff":4},{"id":"big-house-m","kind":"talk","text":"Jack Hartley","sub":"A sharp-dressed man in a rumpled waistcoat, with a red heart tattooed on one hand. Cheerful, chatty.","acts":[1,2,3],"diff":4,"subjects":[{"id":"big-house-n","name":"Crime","info":"He found two £20 notes on the pavement. The luck law allows one big note or two small ones, no more, in any twelve-hour period. He should have simply had worse luck."},{"id":"big-house-o","name":"Mr. Whitlock","info":"Tock asked him a question, and he couldn’t answer. Silence was taken as refusal."}]},{"id":"big-house-p","kind":"talk","text":"Mr. Whitlock","sub":"A twitchy man in a worn waistcoat, with pink-rimmed eyes and a broken watch he checks constantly. He’s mute.","acts":[1,2,3],"diff":4},{"id":"big-house-q","kind":"object","text":"Whitlock's Pencil","sub":"A stub of pencil, halfway used.","acts":[1,2,3],"diff":4}],"desc":"A twin of the first cell, but with a card table and a ticking cuckoo clock."},{"id":"big-house-r","name":"The Window","items":[{"id":"big-house-s","kind":"see","text":"Corridor","sub":"A narrow stone corridor between the cells, with a barred window at the end that looks onto the room.","acts":[1,2,3],"diff":4},{"id":"big-house-t","kind":"see","text":"Barred front window","sub":"Alice’s view of Officer Tock. His clock face is as wide as the house.","acts":[1,2,3],"diff":4},{"id":"big-house-u","kind":"talk","text":"Officer Tock","sub":"A huge policeman in a navy uniform, with a round clock face where his head should be, its hands ticking in the quiet. His mouth is a hinged slot beneath the dial. When it flaps open, brass gears turn inside.","acts":[1,2,3],"diff":4,"subjects":[{"id":"big-house-v","name":"Absalom","info":"Prisoner Absalom. Remained abroad after the curfew bell. The Curfew (Amendment) Act 1884, Section 13: every citizen shall return to their dwelling by the bell. Lack of a dwelling is not grounds for exemption."},{"id":"big-house-w","name":"Hartley","info":"Prisoner Hartley. Discovered two twenty-pound notes upon the pavement. The Fortune (Offences) Act 1971, Section 4: no citizen shall come into more than one large note, two small notes or five lucky pennies in any twelve-hour period. Excess fortune is unlawful gain. He ought simply to have had worse luck."},{"id":"big-house-x","name":"Whitlock","info":"Prisoner Whitlock. Summoned and asked a direct question. The Testimony (Miscellaneous Provisions) Act 1952, Section 9: any citizen summoned shall give testimony aloud. Silence shall be taken as refusal."},{"id":"big-house-y","name":"Alice","info":"Prisoner Dodgson. Suspected of the theft of the Mad City clock from District 13. The Larceny Act 1916, Section 1: whosoever takes and carries away the property of another, without consent, commits larceny."}]},{"id":"big-house-z","kind":"interact","text":"Calling Tock","sub":"Tock will approach if there is an emergency or a ruckus, but he will never be tricked twice the same way.","acts":[1,2,3],"diff":4},{"id":"big-house-10","kind":"interact","text":"Watched","sub":"Every sneaky action done while Tock is watching and not distracted adds +2 to the next roll, cumulative. A caught attempt adds +2 to everything for the rest of the scenario. Anything fishy while he’s alert returns you to your cell, and he confiscates whatever you used.","acts":[1,2,3],"diff":4},{"id":"big-house-11","kind":"danger","text":"Jam Tock’s gears","sub":"With the jam and spoon. Makes him dazed (-2 to difficulty).","acts":[1,2,3],"diff":4},{"id":"big-house-12","kind":"danger","text":"Lift the hook.","sub":"With an extension.","acts":[1,2,3],"diff":4},{"id":"big-house-13","kind":"see","text":"Newspaper","sub":"A broadsheet the size of a barn door.","acts":[1,2,3],"diff":4},{"id":"big-house-14","kind":"see","text":"Armchair","sub":"A worn leather armchair beside the table.","acts":[1,2,3],"diff":4},{"id":"big-house-15","kind":"see","text":"Brass hook","sub":"A small brass hook on the outside of the house front, holding the whole wall shut. A seam runs beside it.","acts":[1,2,3],"diff":4},{"id":"big-house-16","kind":"see","text":"Tin","sub":"A flat tin in his breast pocket.","acts":[1,2,3],"diff":4},{"id":"big-house-17","kind":"see","text":"Law book","sub":"A thick book on a stand beside the chair, the Book of Laws.","acts":[1,2,3],"diff":4},{"id":"big-house-18","kind":"object","text":"Release tablets","sub":"Three small white tablets, stamped RELEASE.","acts":[1,2,3],"diff":4},{"id":"big-house-19","kind":"object","text":"Reduction tablets","sub":"Three small gray tablets, each stamped REDUCTION.","acts":[1,2,3],"diff":4}],"desc":"A narrow stone corridor ends in a wide barred window, with a vast room beyond."},{"id":"big-house-1a","name":"Tabletop","items":[{"id":"big-house-1b","kind":"interact","text":"Stomped house","sub":"The Big House lies on its side on the floor, crushed flat by a boot. The roof has caved in, and the walls have split like eggshells. Bits of brick, iron and torn blanket litter the floor. Tock stands over it, ticking.","acts":[3],"diff":4},{"id":"big-house-1c","kind":"see","text":"Tabletop","sub":"A vast field of polished oak.","acts":[1,2,3],"diff":4},{"id":"big-house-1d","kind":"see","text":"Table edge","sub":"A drop of 60 centimeters, which is a cliff at her size.","acts":[1,2,3],"diff":4},{"id":"big-house-1e","kind":"danger","text":"Parachute down.","sub":"With the blanket.","acts":[1,2,3],"diff":4},{"id":"big-house-1f","kind":"danger","text":"Jump down.","sub":"Without the blanket.","acts":[1,2,3],"diff":10},{"id":"big-house-1g","kind":"see","text":"Floor grate","sub":"At the foot of the table, a corner grate that’s just big enough for someone small.","acts":[1,2,3],"diff":4}],"desc":"A vast plain of polished oak, scattered with crumbs the size of boulders and ending in a sheer drop. The wood is cool and slick underfoot, and smells of beeswax and old biscuits."}],"boons":[{"id":"big-house-1h","name":"Reduction and Release pills","note":""}],"desc":"A dollhouse-sized Victorian prison on a heavy oak table, in the back office of a courthouse. A policeman with a clock for a head sits beside it, ticking steadily.","nightmare":"Officer Tock","crashDesc":"Put back behind bars, if out, otherwise, nothing.","favText":"Reduction and Release pills","starts":["c6"],"x":840,"y":800},{"id":"bazaar","name":"The Bizarre Bazaar","subs":[],"boons":[{"id":"bazaar-0","name":"King's Summons","note":""}],"nightmare":"Guttersnipes","favText":"King's Summons","x":440,"y":40},{"id":"chop-shop","name":"The Chop Shop","subs":[{"id":"chop-shop-0","name":"Freezer","items":[{"id":"chop-shop-1","kind":"interact","text":"Arriving","sub":"Jack has crawled out of a low square hatch into freezing air. The hatch has swung shut behind him before disappearing. (Starts Hungry)","acts":[1],"diff":4},{"id":"chop-shop-2","kind":"see","text":"Hanging carcasses","sub":"About thirty frost-furred carcasses hang in rows from overhead rails: beef, pigs and a few that looks human, but it's hard to tell with the frost.","acts":[1,2,3],"diff":4},{"id":"chop-shop-3","kind":"object","text":"Small carcass","sub":"A skinned, frozen thing about the size of a lamb, roughly 12 kilograms.","acts":[1,2,3],"diff":4},{"id":"chop-shop-4","kind":"see","text":"Overhead rails","sub":"Steel tracks run across the ceiling and out through a slot above the door.","acts":[1,2,3],"diff":4},{"id":"chop-shop-5","kind":"see","text":"Empty hook","sub":"One hook at the end of a row hangs bare, at about shoulder height.","acts":[1,2,3],"diff":4},{"id":"chop-shop-6","kind":"see","text":"Freezer door","sub":"Thick steel, with a long chrome handle. To the Aging Room.","acts":[1,2,3],"diff":4},{"id":"chop-shop-7","kind":"see","text":"Emergency release","sub":"A green knob on the inside of the door, furred with frost.","acts":[1,2,3],"diff":4},{"id":"chop-shop-8","kind":"danger","text":"Free the release","sub":"Frost has sealed the knob. A few hard knocks break it loose.","acts":[1,2,3],"diff":2},{"id":"chop-shop-9","kind":"interact","text":"Safe","sub":"The freezer blocks all sound and smells, making it the safest place back here.","acts":[1,2,3],"diff":4}],"desc":"A vast, white room of hanging meat in freezing air. Breath fogs and frost crunches underfoot."},{"id":"chop-shop-a","name":"Aging Room","items":[{"id":"chop-shop-b","kind":"see","text":"Beef sides","sub":"About twenty dark red sides hang in rows, furred in white and green mold.","acts":[1,2,3],"diff":4},{"id":"chop-shop-c","kind":"interact","text":"Ripe air","sub":"The stink of rot is thick enough to hide Jack’s scent.","acts":[1,2,3],"diff":4},{"id":"chop-shop-d","kind":"interact","text":"Between the sides","sub":"It's possible to hide between the sides.","acts":[1,2,3],"diff":4},{"id":"chop-shop-e","kind":"see","text":"Drip trays","sub":"Steel trays under the meat hold dark liquid, with a drip falling into each. One lies on its side near the curtain, and a dark, oily slick has spread from it across a third of the floor.","acts":[1,2,3],"diff":4},{"id":"chop-shop-f","kind":"danger","text":"Cross the slick floor.","sub":"Jack’s boots slide on the film, and a fall means a loud clatter of limbs or a knocked tray.","acts":[1,2,3],"diff":2},{"id":"chop-shop-g","kind":"see","text":"Freezer door","sub":"Heavy duty, metal. To the Freezer.","acts":[1,2,3],"diff":4},{"id":"chop-shop-h","kind":"see","text":"Strip curtain","sub":"Heavy clear plastic strips, stained yellow, hang across the doorway to the Breaking Room.","acts":[1,2,3],"diff":4}],"desc":"A dim, dripping room where meat hangs to ripen. The stench of rot and old fat is overpowering, thick enough to taste. A fan drones overhead, and the damp air clings to the skin."},{"id":"chop-shop-i","name":"Breaking Room","items":[{"id":"chop-shop-j","kind":"see","text":"Band saw","sub":"A floor-standing saw about 2 meters tall, with a blade as long as a man’s arm. It is switched off.","acts":[1,2,3],"diff":4},{"id":"chop-shop-k","kind":"see","text":"Meat grinder","sub":"A steel hopper about 1.5 meters wide on a heavy stand. It is switched off.","acts":[1,2,3],"diff":4},{"id":"chop-shop-l","kind":"see","text":"Steel tables","sub":"Two long tables, about 3 meters each, with open space underneath.","acts":[1,2,3],"diff":4},{"id":"chop-shop-m","kind":"object","text":"Butcher’s cleaver","sub":"A wide steel blade about 25 centimeters long on a wooden handle.","acts":[1,2,3],"diff":4},{"id":"chop-shop-n","kind":"see","text":"Carcass rail","sub":"Half-carcasses wait on the overhead rail for the saw.","acts":[1,2,3],"diff":4},{"id":"chop-shop-o","kind":"see","text":"Window","sub":"A wide, grimy window at head height. Through it, Shambles works at his block, chopping at a gnarling piece of meat.","acts":[1,2,3],"diff":4},{"id":"chop-shop-p","kind":"interact","text":"Hound hunts","sub":"(After the Hound is loose.) If Jack is alone here, the Hound attacks him. If Shambles is distracted here, it attacks him instead.","acts":[1,2,3],"diff":4},{"id":"chop-shop-q","kind":"interact","text":"Hound unleashed","sub":"Left to its own accord, a very hungry Hound will be seen feeding on Shambles' body in the Breaking room.","acts":[3],"diff":4},{"id":"chop-shop-r","kind":"danger","text":"Hide.","sub":"From Shambles.","acts":[1,2,3],"diff":4},{"id":"chop-shop-s","kind":"danger","text":"Escape Shambles.","sub":"Harder if not hidden first.","acts":[1,2,3],"diff":6},{"id":"chop-shop-t","kind":"danger","text":"Escape the Hound.","sub":"If not attacking Shambles.","acts":[1,2,3],"diff":6},{"id":"chop-shop-u","kind":"see","text":"Strip curtain","sub":"Heavy clear plastic strips, stained yellow, lead back to the Aging Room.","acts":[1,2,3],"diff":4},{"id":"chop-shop-v","kind":"see","text":"Swing door","sub":"It leads on to the Cutting Room.","acts":[1,2,3],"diff":4}],"desc":"A bright, tiled room of cold steel machines, lit by harsh white strip lights. The air smells of bleach and raw blood, and the damp floor is slick underfoot."},{"id":"chop-shop-w","name":"Cutting Room","items":[{"id":"chop-shop-x","kind":"see","text":"Shambles","sub":"A hulking man in a rubber apron and a stitched leather hood, chopping at the block in a steady rhythm of three strokes and a pause.","acts":[1,2,3],"diff":4},{"id":"chop-shop-y","kind":"see","text":"The Hound","sub":"A huge dog-like beast chained across the block, about 2.5 meters long and still alive, with half of one flank already gone.","acts":[1,2,3],"diff":4},{"id":"chop-shop-z","kind":"interact","text":"The Hound slips free","sub":"When Shambles leaves the block, the chains slide off their hooks. The Hound drops to the floor and starts to hunt by smell.","acts":[1,2,3],"diff":4},{"id":"chop-shop-10","kind":"see","text":"Butcher’s block","sub":"About 3 meters long and a meter thick, chopped hollow in the middle.","acts":[1,2,3],"diff":4},{"id":"chop-shop-11","kind":"object","text":"Bolt stunner","sub":"A heavy steel pistol. Pressed to a creature’s head, it drops the target for a few moments.","acts":[1,2,3],"diff":4},{"id":"chop-shop-12","kind":"see","text":"Hung hounds","sub":"bout eight dog-sized hounds hang by their hind legs from hooks above, alive and snarling.","acts":[1,2,3],"diff":4},{"id":"chop-shop-13","kind":"interact","text":"Barking hounds","sub":"Anyone who comes in sets the lesser hounds snarling and barking.","acts":[1,2,3],"diff":4},{"id":"chop-shop-14","kind":"see","text":"Breaking Room window","sub":"The same grimy window, seen from this side.","acts":[1,2,3],"diff":4},{"id":"chop-shop-15","kind":"see","text":"Swing door","sub":"The way back to the Breaking Room.","acts":[1,2,3],"diff":4},{"id":"chop-shop-16","kind":"see","text":"Shop door","sub":"A swing door with a round window, with the shop’s light behind it.","acts":[1,2,3],"diff":4}],"desc":"A narrow, red-lit room that stinks of fresh blood and wet fur. Steady chopping shakes the floor."},{"id":"chop-shop-17","name":"Shop","items":[{"id":"chop-shop-18","kind":"see","text":"Hanging game","sub":"Rabbits, ducks and strings of sausages hang by the window.","acts":[1,2,3],"diff":4},{"id":"chop-shop-19","kind":"see","text":"Display case","sub":"Glass-fronted and chilled, about 3 meters long, with trays of meat in every shade.","acts":[1,2,3],"diff":4},{"id":"chop-shop-1a","kind":"interact","text":"Meat for meat","sub":"Shambles only accepts meat for meat. Any creature, preferably dead or unconscious, will do it.","acts":[1,2,3],"diff":4},{"id":"chop-shop-1b","kind":"object","text":"Stinking shank","sub":"A gray-green shank, still cold, with a smell that makes the eyes water.","acts":[1,2,3],"diff":4},{"id":"chop-shop-1c","kind":"object","text":"Prime rib","sub":"A thick, glistening red cut with white marbling and a smell that makes the mouth water.","acts":[1,2,3],"diff":4},{"id":"chop-shop-1d","kind":"object","text":"Marrow joint","sub":"A bone-in joint about 60 centimeters long, heavy and dense.","acts":[1,2,3],"diff":4},{"id":"chop-shop-1e","kind":"see","text":"Brass bell","sub":"It stands on the counter, with a card reading “Ring for service”.","acts":[1,2,3],"diff":4},{"id":"chop-shop-1f","kind":"see","text":"Street door","sub":"Glass-paned, with a CLOSED sign and a bell above it. The street shows through the glass.","acts":[1,2,3],"diff":4},{"id":"chop-shop-1g","kind":"see","text":"Cutting Room door","sub":"A swing door with a round window, back to the Cutting Room.","acts":[1,2,3],"diff":4}],"desc":"A clean, bright butcher’s shop, cold and orderly after the back rooms. The air smells of sawdust, cold meat and bleach."}],"boons":[{"id":"chop-shop-1h","name":"Bolt stunner","note":""}],"desc":"A butcher’s shop on a grimy street, with a clean white counter at the front and a long line of cold, bloody rooms behind it. The air smells of bleach, sawdust and old meat.","nightmare":"Shambles","crashDesc":"If Shambles is around, he'll hook them in the Cutting Room (8 to escape), if not they'll wake up to the Hound feeding (8 to escape).","favText":"Bolt stunner","starts":["c3"],"x":1240,"y":800},{"id":"counting-house","name":"The Counting House","subs":[{"id":"counting-house-0","name":"The Belfry","items":[]},{"id":"counting-house-1","name":"The Coffer","items":[]}],"boons":[{"id":"counting-house-2","name":"The Clock","note":"Guarded in the Belfry, heavily guarded, fixed in the Royal Seal."},{"id":"counting-house-3","name":"The King's True Name","note":"Hidden like a needle in a haystack in the Coffer."}],"nightmare":"The Wax King","x":40,"y":1180},{"id":"crack-house","name":"The Crack House","subs":[{"id":"crack-house-0","name":"Landing","items":[{"id":"crack-house-1","kind":"see","text":"The crack","sub":"About 6 meters wide at the top, with torn plaster and rebar on both sides. The far edge is level with the floor.","acts":[1,2,3],"diff":4},{"id":"crack-house-2","kind":"see","text":"The drop","sub":"Black, with no bottom in sight. Cold air breathes up from it.","acts":[1,2,3],"diff":4},{"id":"crack-house-3","kind":"see","text":"Door 4","sub":"A polished brass 4, with a doormat in front. Dot's","acts":[1,2,3],"diff":4},{"id":"crack-house-4","kind":"see","text":"Door 7","sub":"A peeling sticker, with a chain, a bolt and three locks. Gaz's","acts":[1,2,3],"diff":4},{"id":"crack-house-5","kind":"see","text":"Far landing","sub":"The other half of the corridor, across the gap, with a lit door and a street exit.","acts":[1,2,3],"diff":4}],"desc":"A narrow, crumbling corridor ending at the edge of the crack. Cold air rises from the drop."},{"id":"crack-house-6","name":"Squat","items":[{"id":"crack-house-7","kind":"interact","text":"Arriving","sub":"Toad comes to on a mattress, shaking, as the bulb buzzes. He hears Big Terry asking Mouse to give the syringe so Fuckwit lets them go.","acts":[1],"diff":4},{"id":"crack-house-8","kind":"see","text":"Junkies","sub":"Five or six figures slumped on filthy mattresses, gaunt and twitching. Catatonic.","acts":[1,2,3],"diff":4},{"id":"crack-house-9","kind":"see","text":"Stained mattresses","sub":"Tossed in heaps, with burnt foil, lighters and bent spoons everywhere.","acts":[1,2,3],"diff":4},{"id":"crack-house-a","kind":"talk","text":"Mouse","sub":"A thin young woman in a hoodie, with sores on her arms. She's holding a syringe, which she refuses to let go of.","acts":[1,2,3],"diff":4},{"id":"crack-house-b","kind":"danger","text":"Pry the syringe from Mouse.","sub":"She is scared and desperate, and she will fight for it.","acts":[1,2,3],"diff":4},{"id":"crack-house-c","kind":"object","text":"Clean Fix","sub":"A syringe of white-pink liquid. It clears all withdrawal and leaves a clear head.","acts":[1,2,3],"diff":4},{"id":"crack-house-d","kind":"interact","text":"Using the Clean Fix","sub":"Any mental status is cleared, including Lost Hours, clearing one count of it. Using it without any Lost Hours gives the condition \"Clear mind\", and it cancels the next count of Lost Hours.","acts":[1,2,3],"diff":4},{"id":"crack-house-e","kind":"talk","text":"Big Terry","sub":"A broad man in a faded football shirt. He talks slowly.","acts":[1,2,3],"diff":4,"subjects":[{"id":"crack-house-f","name":"Mouse","info":"Fuckwit called her “so fucking scared,” and now she's scared of everything."},{"id":"crack-house-g","name":"Big Terry","info":"Fuckwit called him “fucking heavy,” and now his body feels like lead. He cannot lift his arms."},{"id":"crack-house-h","name":"Pickle","info":"Fuckwit told him to “shut the fuck up,” and now he can't talk."},{"id":"crack-house-i","name":"Clean Fix","info":"It clears your head fully: fear, guilt, headaches, it's the best. They used it all, and Fuckwit wants the dose that Mouse has, but she won't let go."},{"id":"crack-house-j","name":"Fuckwit","info":"He's an asshole. He made the crack by saying it was \"fucking huge\". He said he was going to let us pass if we gave him the last Clean Fix."}]},{"id":"crack-house-k","kind":"talk","text":"Pickle","sub":"A wiry man with raw gums and cracked lips. He can't talk but gestures erratically.","acts":[1,2,3],"diff":4},{"id":"crack-house-l","kind":"see","text":"Front door","sub":"To the landing.","acts":[1,2,3],"diff":4}],"desc":"A stuffy, windowless flat reeking of burnt chemicals and unwashed bodies. A bare bulb buzzes overhead. The floor is sticky and the air is warm and sour."},{"id":"crack-house-m","name":"Dot's Flat","items":[{"id":"crack-house-n","kind":"talk","text":"Dot","sub":"A frail old woman in a cardigan, terrified of Fuckwit.","acts":[1,2,3],"diff":4},{"id":"crack-house-o","kind":"danger","text":"Convince Dot to open the door","sub":"Otherwise, she keeps it cracked open, the chain still on.","acts":[1,2,3],"diff":4},{"id":"crack-house-p","kind":"see","text":"Armchair","sub":"Worn flat, facing a small television that plays static.","acts":[1,2,3],"diff":4},{"id":"crack-house-q","kind":"object","text":"Biscuit tin","sub":"A lighthouse tin of plain digestives.","acts":[1,2,3],"diff":4},{"id":"crack-house-r","kind":"object","text":"Ironing board","sub":"A folding steel frame, about 1.5 meters long and 30 centimeters wide, with a padded top.","acts":[1,2,3],"diff":4},{"id":"crack-house-s","kind":"see","text":"Front door","sub":"Back to the landing.","acts":[1,2,3],"diff":4}],"desc":"A warm, tidy flat that smells of lavender, tea and gas fire. A kettle ticks as it cools, and the television hisses static."},{"id":"crack-house-t","name":"Gaz's Flat","items":[{"id":"crack-house-u","kind":"talk","text":"Gaz","sub":"A twitchy man in a tracksuit, maybe thirty, who sells to the squat.","acts":[1,2,3],"diff":4,"subjects":[{"id":"crack-house-v","name":"Fuckwit","info":"He sells to Fuckwit, but he's out. He took everything and is pissed at him that he's empty-handed. He's a psycho."},{"id":"crack-house-w","name":"Spare door","info":"It belongs to a flat he cleared out. He would be glad to see it gone, if you do not make a fuss."},{"id":"crack-house-x","name":"Gun","info":"He's not going out there to fight Fuckwit, he knows what he can do. And he's not giving it away."},{"id":"crack-house-y","name":"Clean Fix","info":"He was robbed by Fuckwit. He knows how to get more, but don't want to tell anyone. He pretends not to. \"He doesn't remember\"."}]},{"id":"crack-house-z","kind":"danger","text":"Get Gaz talking.","sub":"He'll tell you of his dealer, Nibs Bodkin, at the Bazaar. He gives you a silver lighter that he needs to return to him. Say they're friends with him.","acts":[1,2,3],"diff":4},{"id":"crack-house-10","kind":"object","text":"Gaz’s pistol","sub":"A small, scratched black pistol. Loaded.","acts":[1,2,3],"diff":4},{"id":"crack-house-11","kind":"danger","text":"Convince Gaz to open the door","sub":"Not worth the trouble. Sorry, kid.","acts":[1,2,3],"diff":6},{"id":"crack-house-12","kind":"see","text":"Mini fridge","sub":"Humming, full of cans of lager.","acts":[1,2,3],"diff":4},{"id":"crack-house-13","kind":"see","text":"Scales and baggies","sub":"On a coffee table, under a lamp.","acts":[1,2,3],"diff":4},{"id":"crack-house-14","kind":"see","text":"Spare door","sub":"A front door off its hinges, leaning against the wall, with a brass number 9.","acts":[1,2,3],"diff":4},{"id":"crack-house-15","kind":"see","text":"Front door","sub":"Back to the landing.","acts":[1,2,3],"diff":4}],"desc":"A cramped, airless flat, stacked with boxes. It smells of cardboard, stale lager and weed. A fridge hums in the corner."},{"id":"crack-house-16","name":"Far Landing","items":[{"id":"crack-house-17","kind":"talk","text":"Fuckwit","sub":"A greedy, pinched man in a stained suit jacket, with a gold chain.","acts":[1,2,3],"diff":4,"subjects":[{"id":"crack-house-18","name":"Clean Fix","info":"These junkies stole his shit, he's not letting anyone out until they give it back."},{"id":"crack-house-19","name":"\"You're a tiny fucking runt.\"","info":"Shrinks them to half size."},{"id":"crack-house-1a","name":"\"You're so fucking stupid.\"","info":"Gains \"Fucking stupid\" status."},{"id":"crack-house-1b","name":"\"You're slow as fuck!\"","info":"Target moves as if wading through glue."},{"id":"crack-house-1c","name":"“This is a big fucking knife.”","info":"A kitchen knife swells to the length of a sword."}]},{"id":"crack-house-1d","kind":"interact","text":"Getting rid of statuses.","sub":"Killing Fuckwit, or taking a Clean Fix, fixes it.","acts":[1,2,3],"diff":4},{"id":"crack-house-1e","kind":"danger","text":"Trick Fuckwit","sub":"To get him to say something that'll bite him in the ass. He is paranoid, but can't stop swearing.","acts":[1,2,3],"diff":4},{"id":"crack-house-1f","kind":"danger","text":"Throw the syringe across","sub":"","acts":[1,2,3],"diff":6},{"id":"crack-house-1g","kind":"danger","text":"Don’t fall.","sub":"You catch the edge for a moment.","acts":[1,2,3],"diff":6},{"id":"crack-house-1h","kind":"danger","text":"Land without getting hurt.","sub":"It's a big fall.","acts":[1,2,3],"diff":10},{"id":"crack-house-1i","kind":"danger","text":"Cross to the other side.","sub":"On an object. Harder if Fuckwit tries to stop them.","acts":[1,2,3],"diff":2},{"id":"crack-house-1j","kind":"danger","text":"Find your way out.","sub":"If fallen down, succeed to get to the Breaker's Yard.","acts":[1,2,3],"diff":6},{"id":"crack-house-1k","kind":"see","text":"Fuckwit's Flat","sub":"A door ajar to a room piled to the ceiling with junk: televisions, bikes, suitcases and a rusted safe.","acts":[1,2,3],"diff":4},{"id":"crack-house-1l","kind":"interact","text":"Searching the flat","sub":"Nothing but junk, dirty clothes, and garbage. It reeks.","acts":[1,2,3],"diff":4},{"id":"crack-house-1m","kind":"see","text":"Street door","sub":"Leads to the Bazaar.","acts":[1,2,3],"diff":4},{"id":"crack-house-1n","kind":"interact","text":"\"I'm fucking huge!\"","sub":"Fuckwit is a giant, smashing at Gaz's door, trying to get him out so he can get more drugs from him. Gaz and Dot are the only survivors, the others have been killed, smashed and crushed by him.","acts":[3],"diff":4}],"desc":"A bare corridor, lit by the glass street door at its end."}],"boons":[{"id":"crack-house-1o","name":"Clean Fix","note":""}],"desc":"A tenement split from roof to cellar, its two halves leaning apart over a black gap. Cold air breathes up from below.","nightmare":"Fuckwit","crashDesc":"The junkies steal whatever they have. Otherwise, not much else to lose here.","favText":"Clean Fix","starts":["c1"],"x":440,"y":1180},{"id":"highschool","name":"The High School","subs":[],"nightmare":"Mother When","x":680,"y":450},{"id":"hoggery","name":"The Hoggery","subs":[{"id":"hoggery-0","name":"Pens","items":[{"id":"hoggery-1","kind":"danger","text":"Save Mr. Hickory.","sub":"Prying it away from the hogs. If they swallow him, it'll have to be extracted.","acts":[1],"diff":4},{"id":"hoggery-2","kind":"interact","text":"Mr. Wolfe arrives","sub":"A few minutes after Henry arrives, the phone from the booth will ring, and Mr. Wolfe will arrive calmly, ready for his inspection.","acts":[1],"diff":4},{"id":"hoggery-3","kind":"see","text":"Six fat hogs","sub":"With sagging skin and uneven tusks, pacing the sties and squealing.","acts":[1,2,3],"diff":4},{"id":"hoggery-4","kind":"see","text":"Troughs","sub":"A line of them, running from the sties toward the shore. A thin layer of pearly silt at the bottom of the troughs, faintly glowing and shifting between white, pink and green.","acts":[1,2,3],"diff":4},{"id":"hoggery-5","kind":"talk","text":"Mr. Hogg","sub":"A thin, stooped man in his sixties, in patched overalls and rubber boots. His hands are cracked from years of work and his voice is soft and tired. He is polite and humble, and he is afraid of Wolfe. He loves his hogs and talks about them like family.","acts":[1,2,3],"diff":4,"subjects":[{"id":"hoggery-6","name":"Bells","info":"That announces the 13th hour. Usually it chimes again when the hour is over. If this goes on, his hogs will starve. He knows the Clock is kept at the Wax King's Counting House, maybe there's a problem with it."},{"id":"hoggery-7","name":"Hogs","info":"This is all he owns, and they need each other. He gives them Spirits runoff, and he uses their droppings to make fruit, which he lives off of. Their names are Agnes, Mabel, Dolly, Gertie, Winnie and Maud."},{"id":"hoggery-8","name":"Runoff","info":"Spirits come from the City Slumbering. It runs through the Wax King first, who mints it, and then through the Warrens, where many take their share. The runoff washes down the lake, and he sifts them at the docks and feeds them to the hogs. The runoffs aren't enough to satiate a man, but their droppings fertilize the ground and grow the fruit he lives on."},{"id":"hoggery-9","name":"Debt","info":"Wolfe gave him the island in exchange for one hog, and he never could let himself give a hog away. The interest grew to six hogs, so he hides them every time Mr. Wolfe comes."},{"id":"hoggery-a","name":"Wolfe","info":"He inspects the barn for hogs every 13th hour, but always runs out of time after an hour. That's why he's moving to hide them under the farmhouse. That's why he never found out the space under the farmhouse."},{"id":"hoggery-b","name":"Fruits","info":"Three are ripe. He gives one freely, and the other two need convincing."},{"id":"hoggery-c","name":"Gleaners","info":"He keeps away from the water and never swims. He does not know where they came from, only that they feed on the Spirits."},{"id":"hoggery-d","name":"Canoe","info":"He used to go upstream in it, but it sank this morning and is too afraid to try and reach it."}]},{"id":"hoggery-e","kind":"interact","text":"Open / close the sty gates.","sub":"Easily climbable, they can be locked.","acts":[1,2,3],"diff":4},{"id":"hoggery-f","kind":"interact","text":"The hogs go hungry.","sub":"As time runs on, the hogs will grow very hungry. At a point, even Mr. Hogg will remark he could fill the lake with Spirits and they wouldn't be satiated.","acts":[2,3],"diff":4}],"desc":"A muddy yard hemmed in by wooden sties. Thick mud sucks at every step, and the stench of manure and wet straw hangs in the cold air. The hogs squeal without pause."},{"id":"hoggery-g","name":"Farmhouse","items":[{"id":"hoggery-h","kind":"interact","text":"Reduced to rubble","sub":"If Mr. Wolfe knocked down the house, it is now a pile of rubble.","acts":[2,3],"diff":4},{"id":"hoggery-i","kind":"see","text":"Kitchen table","sub":"Two mismatched chairs and a tin plate with a few crumbs on it.","acts":[1,2,3],"diff":4},{"id":"hoggery-j","kind":"object","text":"Kitchen knife","sub":"A long carving knife, nicked and worn thin.","acts":[1,2,3],"diff":4},{"id":"hoggery-k","kind":"object","text":"Cast-iron pan","sub":"About 30 centimeters across, black with old grease.","acts":[1,2,3],"diff":4},{"id":"hoggery-l","kind":"see","text":"Wood stove","sub":"Cast iron, in the corner, with a kettle on top and split logs beside it.","acts":[1,2,3],"diff":4},{"id":"hoggery-m","kind":"object","text":"Oil lantern","sub":"Brass, with about two hours of oil left.","acts":[1,2,3],"diff":4},{"id":"hoggery-n","kind":"see","text":"Dresser","sub":"Heavy and wooden, against the back wall. Scuff marks on the floor run from its feet to the side.","acts":[1,2,3],"diff":4},{"id":"hoggery-o","kind":"see","text":"Bed","sub":"Narrow, in the bedroom doorway, with a thin gray blanket pulled tight.","acts":[1,2,3],"diff":4},{"id":"hoggery-p","kind":"interact","text":"Push the dresser.","sub":"It is heavy, but the floor is smooth.","acts":[1,2,3],"diff":4},{"id":"hoggery-q","kind":"interact","text":"Crawlspace","sub":"Behind the dresser, a sloped passage about a meter wide runs down inside the wall to the space under the house.","acts":[1,2,3],"diff":4},{"id":"hoggery-r","kind":"interact","text":"Front door","sub":"Leads out to the pens.","acts":[1,2,3],"diff":4},{"id":"hoggery-s","kind":"interact","text":"Back door","sub":"Leads out to the backyard.","acts":[1,2,3],"diff":4}],"desc":"A cramped, dim kitchen with a low ceiling. The floorboards creak underfoot, and the warm air smells of woodsmoke and old fat."},{"id":"hoggery-t","name":"Under the House","items":[{"id":"hoggery-u","kind":"see","text":"Lattice panels","sub":"Thin gray light slips through the gaps in the wooden slats along the outer edge.","acts":[1,2,3],"diff":4},{"id":"hoggery-v","kind":"see","text":"Stilts","sub":"Thick, mossy posts, spaced about 2 meters apart, holding up the floor above.","acts":[1,2,3],"diff":4},{"id":"hoggery-w","kind":"interact","text":"Sloped passage","sub":"It climbs back up inside the wall to the farmhouse kitchen.","acts":[1,2,3],"diff":4}],"desc":"A low, cramped crawlspace, dark except for thin gray light at the edges. The air is cold and smells of damp earth and mildew."},{"id":"hoggery-x","name":"Backyard","items":[{"id":"hoggery-y","kind":"see","text":"Orchard","sub":"A handful of small, crooked fruit trees in soft, dark soil, about 15 meters across.","acts":[1,2,3],"diff":4},{"id":"hoggery-z","kind":"object","text":"Ripe fruit","sub":"Like an orange pear. Heavy and slightly warm, about the size of a fist.","acts":[1,2,3],"diff":4},{"id":"hoggery-10","kind":"interact","text":"Eating the fruit.","sub":"Gives +1 Hope. Eating the last one without permission instead gives +1 Despair.","acts":[1,2,3],"diff":4},{"id":"hoggery-11","kind":"see","text":"Face tree","sub":"An old, gnarled tree at the back of the yard, with the shape of a human face in the bark. Gray, glassy lumps crust the face tree’s bar, trapping insects at places.","acts":[1,2,3],"diff":4},{"id":"hoggery-12","kind":"danger","text":"Harvest the resin","sub":"The screams of the tree are unbearable, and cause a great headache.","acts":[1,2,3],"diff":4},{"id":"hoggery-13","kind":"object","text":"Gray putty","sub":"A thick gray ball of resin. Very sticky, and very sturdy.","acts":[1,2,3],"diff":4},{"id":"hoggery-14","kind":"see","text":"Manure mounds","sub":"Dark heaps between the trees, where the hogs’ droppings have been worked into the soil.","acts":[1,2,3],"diff":4},{"id":"hoggery-15","kind":"see","text":"Farmhouse","sub":"The back of the low gray farmhouse, standing on short stilts. A narrow back door sits under a sagging overhang.","acts":[1,2,3],"diff":4},{"id":"hoggery-16","kind":"see","text":"Barn","sub":"A long wooden barn. Its double doors hang slightly open, and the boards are weathered and gapped.","acts":[1,2,3],"diff":4},{"id":"hoggery-17","kind":"interact","text":"Mr. Wolfe's feast","sub":"If Mr. Wolfe wasn't dealt with, he will eat all the hogs, then Mr. Hogg, and nap under tree. If woken up, he'll find himself to have enough room left for desserts.","acts":[1,2,3],"diff":4}],"desc":"A small orchard of crooked trees on dark, soft ground, with a gnarled old tree at the back. The air smells of sweet fruit and manure, and the ground squelches underfoot."},{"id":"hoggery-18","name":"Barn","items":[{"id":"hoggery-19","kind":"see","text":"Feed buckets","sub":"Stacked against the wall, all empty and scraped clean.","acts":[1,2,3],"diff":4},{"id":"hoggery-1a","kind":"object","text":"Bucket","sub":"Metal, sturdy.","acts":[1,2,3],"diff":4},{"id":"hoggery-1b","kind":"see","text":"Tool rack","sub":"A long wooden rack on the side wall, with tools hung from pegs.","acts":[1,2,3],"diff":4},{"id":"hoggery-1c","kind":"object","text":"Hog snare pole","sub":"About 2.5 meters long, with a loop of steel cable at the tip and a handle to tighten it.","acts":[1,2,3],"diff":4},{"id":"hoggery-1d","kind":"object","text":"Pitchfork","sub":"A long-handled, three-tined fork about 1.5 meters long.","acts":[1,2,3],"diff":4},{"id":"hoggery-1e","kind":"object","text":"Hatchet","sub":"A short-handled hatchet with a sharp edge.","acts":[1,2,3],"diff":4},{"id":"hoggery-1f","kind":"see","text":"Hay loft","sub":"A small loft above the doors, with a few loose bales and a ladder leaning against it.","acts":[1,2,3],"diff":4},{"id":"hoggery-1g","kind":"interact","text":"Landing in","sub":"Henry has dropped down a tunnel into soft hay in the loft. Outside, Mr. Hogg is shouting at the hogs: “Let that thing go, we have to go!”","acts":[1],"diff":4},{"id":"hoggery-1h","kind":"interact","text":"Ladder","sub":"It climbs to the loft","acts":[1,2,3],"diff":4},{"id":"hoggery-1i","kind":"see","text":"Pens","sub":"Out the doors, six hogs are closing in on Mr. Hickory, laying still on the ground, while Mr. Hogg is shoving at them with a board.","acts":[1],"diff":4},{"id":"hoggery-1j","kind":"see","text":"Pens","sub":"Beside the farmhouse, a row of six wooden sties. Hogs squeal and pace inside them.","acts":[2,3],"diff":4},{"id":"hoggery-1k","kind":"see","text":"Phone booth","sub":"Far down the shore, past the farmhouse, a small red phone booth stands out against the gray gravel.","acts":[1,2,3],"diff":4},{"id":"hoggery-1l","kind":"see","text":"Backyard","sub":"Just outside the doors, a small orchard of crooked trees, with a gnarled old tree at the back.","acts":[1,2,3],"diff":4},{"id":"hoggery-1m","kind":"see","text":"River","sub":"Beyond the farmhouse roof, a strip of dark gray water, ringed by steep mountain walls.","acts":[1,2,3],"diff":4}],"desc":"A dim, drafty barn that smells of old hay and dust. The wind whistles through the gaps in the boards, and the floor is cold and gritty underfoot."},{"id":"hoggery-1n","name":"Phone Booth","items":[{"id":"hoggery-1o","kind":"see","text":"Red glass booth","sub":"Red and spotless, it reminds you of London.","acts":[1,2,3],"diff":4},{"id":"hoggery-1p","kind":"see","text":"Black handset","sub":"It hangs on a steel cord, with a dial and no coin slot.","acts":[1,2,3],"diff":4},{"id":"hoggery-1q","kind":"object","text":"Number card (Hoggery)","sub":"A yellowed paper disc in the center of the dial. The Hoggery's phone number is typed here.","acts":[1,2,3],"diff":4},{"id":"hoggery-1r","kind":"interact","text":"Using the phone","sub":"As long as they have a number to call","acts":[1,2,3],"diff":4},{"id":"hoggery-1s","kind":"interact","text":"Mr. Wolfe arrives","sub":"A few minutes after Henry arrives, the phone from the booth will ring, and Mr. Wolfe will arrive calmly, ready for his inspection.","acts":[1,2,3],"diff":4},{"id":"hoggery-1t","kind":"talk","text":"Barnaby B. Wolfe","sub":"A tall, lean wolf in a tailored pinstripe suit, with slicked-back gray fur and a gold watch. He talks fast and smiles constantly, with his teeth showing.","acts":[1,2,3],"diff":4,"subjects":[{"id":"hoggery-1u","name":"Debt","info":"He gave Mr. Hogg the island for one hog, and the interest has grown to six. He calls it a fair deal."},{"id":"hoggery-1v","name":"Hogs","info":"He wants all six, and he plans to eat them. While Mr. Hogg has, time and time again, affirmed that they have all passed, he still doesn't believe him."},{"id":"hoggery-1w","name":"Booth","info":"Like all the Awake, he has a peculiar ability. His is travelling by telephone."},{"id":"hoggery-1x","name":"13th Hour","info":"He says it is a good time for business, since he knows Mr. Hogg is always here at this hour."}]},{"id":"hoggery-1y","kind":"object","text":"Blow","sub":"A small bottle of white powder. Makes you sneeze with enough force to knock down a house.","acts":[1,2,3],"diff":4},{"id":"hoggery-1z","kind":"interact","text":"Mr. Wolfe's inspection","sub":"He'll look around the property, finishing, and spending most time, turning over the farmhouse. After an hour, he'll get impatient and use his blow.","acts":[1,2,3],"diff":4},{"id":"hoggery-20","kind":"interact","text":"Blowing down the house","sub":"Using blow, Mr. Wolfe will knock down the whole house, reducing it to rubble, This will clearly reveal the slope that leads under the house.","acts":[2],"diff":4},{"id":"hoggery-21","kind":"danger","text":"Convince Mr. Wolfe the hogs are gone.","sub":"If convinced, he'll leave for now, but return in Act 3.","acts":[1,2,3],"diff":8},{"id":"hoggery-22","kind":"danger","text":"Fight Mr. Wolfe","sub":"He uses his teeth and claws to fight.","acts":[1,2,3],"diff":6}],"desc":"A lone red booth stands on the gravel shore, bright against the gray."},{"id":"hoggery-23","name":"Docks","items":[{"id":"hoggery-24","kind":"see","text":"Broken canoe","sub":"A broken canoe, about 4.5 meters long, lying on its side in the shallows next to the pier, 2m deep. Its green paint is chipped, and a fist-sized hole is torn through the hull near the keel. There's an iron ring is bolted to the bow.","acts":[1,2,3],"diff":4},{"id":"hoggery-25","kind":"danger","text":"Fish out the canoe.","sub":"Without any tools, Gleaners will be drawn to them instantly.","acts":[1,2,3],"diff":4},{"id":"hoggery-26","kind":"danger","text":"Fish out the canoe.","sub":"With a short tool (under 2m), Gleaners will try to pull them in.","acts":[1,2,3],"diff":2},{"id":"hoggery-27","kind":"see","text":"Mooring post","sub":"At the end of the pier, with a frayed rope.","acts":[1,2,3],"diff":4},{"id":"hoggery-28","kind":"object","text":"Rope","sub":"A frayed hemp rope, about 6 meters long.","acts":[1,2,3],"diff":4},{"id":"hoggery-29","kind":"interact","text":"Tie a ship to the post","sub":"Boats not tied to it and left alone will float towards the center of the lake.","acts":[1,2,3],"diff":4},{"id":"hoggery-2a","kind":"see","text":"Wooden sluice box","sub":"Lays besides the pier. Has a hand-cranked pump at its head and a fine-mesh screen across its floor, At its foot, there's a wooden tub, dry.","acts":[1,2,3],"diff":4},{"id":"hoggery-2b","kind":"interact","text":"Crank the pump","sub":"Pulls lake water up over the screen, but only plain water comes through.","acts":[1,2,3],"diff":4},{"id":"hoggery-2c","kind":"see","text":"Gleaners","sub":"Pale, translucent figures, drifting just under the water’s surface in slow circles. A dozen are visible from the pier. They have long raking fingers, trailing threads below the waist and round, lipless mouths.","acts":[1,2,3],"diff":4},{"id":"hoggery-2d","kind":"see","text":"Pens","sub":"Up the shore, a row of six wooden sties. Six large squealing hogs pace the pens","acts":[1,2,3],"diff":4},{"id":"hoggery-2e","kind":"see","text":"Farmhouse","sub":"Inland, a low gray farmhouse, standing on short stilts, and a thin line of smoke rises from the chimney.","acts":[1,2,3],"diff":4},{"id":"hoggery-2f","kind":"see","text":"Barn","sub":"Behind the farmhouse, the roof of a long wooden barn.","acts":[1,2,3],"diff":4},{"id":"hoggery-2g","kind":"see","text":"Phone booth","sub":"Away from the pier, at the end of a gravel path. a red phone booth.","acts":[1,2,3],"diff":4}],"desc":"A weathered pier stretches out over dark gray water, ringed by steep mountains. A cold wind carries the smell of damp wood, and the hogs squeal somewhere up the shore."},{"id":"hoggery-2h","name":"River","items":[{"id":"hoggery-2i","kind":"see","text":"Water","sub":"Dark grey, with pale shapes drifting just under the surface.","acts":[1,2,3],"diff":4},{"id":"hoggery-2j","kind":"see","text":"Mountains","sub":"Up on every sides, too steep to climb.","acts":[1,2,3],"diff":4},{"id":"hoggery-2k","kind":"danger","text":"Run the rapids.","sub":"In the patched canoe, it's a rocky, challenging","acts":[1,2,3],"diff":4},{"id":"hoggery-2l","kind":"danger","text":"Swim across the lake.","sub":"The water is cold, and the Gleaners will drag them down.","acts":[1,2,3],"diff":8},{"id":"hoggery-2m","kind":"see","text":"Docks","sub":"Back at the island, a wooden pier juts out over the water.","acts":[1,2,3],"diff":4},{"id":"hoggery-2n","kind":"see","text":"Farmhouse","sub":"Inland, a low gray farmhouse stands on short stilts. A thin line of smoke rises from the chimney.","acts":[1,2,3],"diff":4},{"id":"hoggery-2o","kind":"see","text":"Phone booth","sub":"On the shore near the pier, a lone red phone booth stands out against the gravel.","acts":[1,2,3],"diff":4},{"id":"hoggery-2p","kind":"interact","text":"Dry up the river.","sub":"If the beavers of Wild Wood build a dam, the river is walkable, dried up, the Gleaners shriveled up like jellyfishes. The hogs are also now able to cross it.","acts":[1,2,3],"diff":4}],"desc":"Cold, still water stretches out toward the mountain walls. It smells of damp stone and rot. Nothing makes a sound but the lapping of waves."}],"boons":[{"id":"hoggery-2q","name":"Hogg's Herd","note":"If the route to the Wild Wood is cleared, Hogg's 16 ravenous pigs can be borrowed."}],"desc":"A small mountain-ringed clearing at the end of a lake and river, with a stilted farmhouse, a barn and six fat, ugly hogs squealing in muddy pens. It smells of manure and wet straw, the air is cool and damp, and the dock is slick underfoot.","nightmare":"Barnaby B. wolfe","crashDesc":"Mr. Hogg brought them to his bed. He says he's happy they're fine, but the hogs got to them first and ate something important of theirs, or if not, a limb. If it's Mr. Wolfe instead, he would start by a limb as well, currently cooking on the stove (hand or foot).","starts":["c5"],"x":840,"y":1180},{"id":"main-line","name":"The Main Line","subs":[],"nightmare":"Loco Motive","x":1240,"y":1180},{"id":"playground","name":"The Playground","subs":[{"id":"playground-0","name":"Sandpit","items":[{"id":"playground-1","kind":"see","text":"Sandpit","sub":"A square of damp gray sand, about 4 meters across, in a low wooden frame at the edge of the playground.","acts":[1,2,3],"diff":4},{"id":"playground-2","kind":"see","text":"Playground","sub":"An empty school playground of gray tarmac. Swings on a red frame, a spinning roundabout, a green climbing dome and a wooden tower with a red tube slide. All of it is brightly painted, with no rust, and nothing moves except a slow sway in the chains.","acts":[1,2,3],"diff":4},{"id":"playground-3","kind":"see","text":"Spring rider","sub":"A painted wooden horse on a rusted spring, near the swings. It faces you.","acts":[1,2,3],"diff":4},{"id":"playground-4","kind":"see","text":"Gate","sub":"At the far end, tall iron bars with a brass bell on the post.","acts":[1,2,3],"diff":4},{"id":"playground-5","kind":"interact","text":"Landing","sub":"Ben falls out of the dark sky and hits the sand hard. It knocks the wind out of him, but nothing breaks.","acts":[1],"diff":4},{"id":"playground-6","kind":"interact","text":"Empty playground","sub":"Bare tarmac where the equipment stood, torn up in long gouges. Only broken bolts and holes in the ground remain.","acts":[3],"diff":4},{"id":"playground-7","kind":"interact","text":"Drag trail","sub":"A wide track of churned tarmac and paint flakes leads to the gate.","acts":[3],"diff":4}],"desc":"A damp sandpit at the edge of an empty playground, under a black sky. The air is cold and still, and smells of wet sand and rust. The only sound is the faint creak of chains."},{"id":"playground-8","name":"Hopscotch","items":[{"id":"playground-9","kind":"see","text":"Hopscotch grid","sub":"Faded white squares numbered 1 to 10, painted on the tarmac.","acts":[1,2,3],"diff":4},{"id":"playground-a","kind":"see","text":"Chalk circle","sub":"In the middle of the open tarmac, a lopsided circle about 2 meters across, drawn in thick white chalk.","acts":[1,2,3],"diff":4},{"id":"playground-b","kind":"see","text":"Dead boy","sub":"A boy of about nine lies curled inside the circle, very thin, with his school jumper pulled over his knees. He hasn’t been dead long. A stub of chalk is pinched in his fist.","acts":[1,2,3],"diff":4},{"id":"playground-c","kind":"object","text":"Chalk stub","sub":"A worn stub of white playground chalk, about 3 centimeters long.","acts":[1,2,3],"diff":4},{"id":"playground-d","kind":"interact","text":"Standing in the circle","sub":"Draw a circle around yourself, and while you stand inside it, nothing can reach you.","acts":[1,2,3],"diff":4}],"desc":"A wide stretch of open tarmac."},{"id":"playground-e","name":"Swings","items":[{"id":"playground-f","kind":"see","text":"Swings","sub":"Four swings on a red frame, their chains long and gleaming, with the seats hanging just above the ground. They sway slightly when there’s no wind.","acts":[1,2,3],"diff":4},{"id":"playground-g","kind":"see","text":"Scrape marks","sub":"Pale arcs scratched into the tarmac around the frame, about 4 meters out, where the chains have lashed.","acts":[1,2,3],"diff":4},{"id":"playground-h","kind":"danger","text":"Break free of the chains","sub":"Once caught. On a failure, you’re flung into the Dome.","acts":[1,2,3],"diff":6},{"id":"playground-i","kind":"see","text":"Spring rider","sub":"A painted wooden horse on a rusted spring, its paint chipped, its eyes glossy and wet. Whenever you turn your back, it has turned to face you.","acts":[1,2,3],"diff":4},{"id":"playground-j","kind":"see","text":"Pebbles","sub":"Scattered under the seats.","acts":[1,2,3],"diff":4},{"id":"playground-k","kind":"object","text":"Pebble","sub":"A smooth gray stone, about the size of a thumbnail.","acts":[1,2,3],"diff":4},{"id":"playground-l","kind":"interact","text":"Empty frame holes","sub":"Four deep holes in the tarmac where the frame’s legs were ripped out, with snapped bolts sticking up.","acts":[3],"diff":4}],"desc":"A red swing frame in the middle of the tarmac, its seats hanging still. The chains creak and sway with no wind to move them."},{"id":"playground-m","name":"Roundabout","items":[{"id":"playground-n","kind":"see","text":"Roundabout","sub":"A flat steel disc about 3 meters across, with grab bars, painted bright red and yellow wedges.","acts":[1,2,3],"diff":4},{"id":"playground-o","kind":"see","text":"Spinning","sub":"It turns slowly on its own, creaking.","acts":[1,2,3],"diff":4},{"id":"playground-p","kind":"see","text":"Speeding up","sub":"It spins faster whenever it wants, and anything on it or brushing it gets flung toward the Climbing Dome.","acts":[1,2,3],"diff":4},{"id":"playground-q","kind":"danger","text":"Hold on","sub":"If caught on it. On a failure, you’re thrown into the Dome.","acts":[1,2,3],"diff":6},{"id":"playground-r","kind":"interact","text":"Bare spindle","sub":"A steel post sticking out of the ground.","acts":[3],"diff":4}],"desc":"A painted steel disc, turning slowly on its own with a steady creak. A cold draft stirs as it passes."},{"id":"playground-s","name":"Climbing Dome","items":[{"id":"playground-t","kind":"see","text":"Climbing Dome","sub":"A rounded frame of steel bars, about 3 meters tall, painted bright green, with fresh paint. It sits beside the gate.","acts":[1,2,3],"diff":4},{"id":"playground-u","kind":"see","text":"Seam","sub":"A line runs down the middle of the dome where its two halves meet.","acts":[1,2,3],"diff":4},{"id":"playground-v","kind":"see","text":"Crawl tunnel","sub":"A plastic tube leads from the base of the dome toward the tower.","acts":[1,2,3],"diff":4},{"id":"playground-w","kind":"interact","text":"Snapping shut","sub":"Anything that lands inside, flung or climbing, makes the two halves snap shut. The prey is squeezed into the crawl tunnel and on to the slide.","acts":[1,2,3],"diff":4},{"id":"playground-x","kind":"danger","text":"Escape the Dome","sub":"Before it closes.","acts":[1,2,3],"diff":8},{"id":"playground-y","kind":"interact","text":"Crater","sub":"A round pit in the tarmac where the dome tore itself free, with green paint smeared around the edges.","acts":[3],"diff":4}],"desc":"A bright green dome of steel bars beside the gate, smelling of fresh paint."},{"id":"playground-z","name":"Tower","items":[{"id":"playground-10","kind":"see","text":"Play tower","sub":"A wooden tower about 4 meters tall, with a rope net up one side and a platform at the top.","acts":[1,2,3],"diff":4},{"id":"playground-11","kind":"see","text":"Tube Slide","sub":"A covered spiral slide, bright red, curling down from the platform.","acts":[1,2,3],"diff":4},{"id":"playground-12","kind":"interact","text":"Inside the slide","sub":"Dark, padded and humming, and filled with mucky water. It drains Spirits for as long as you’re inside, but leaves you whole. There's a slingshot in the muck.","acts":[1,2,3],"diff":4},{"id":"playground-13","kind":"object","text":"Slingshot","sub":"A child’s wooden slingshot with a thick rubber band. It can hit a target 10m away.","acts":[1,2,3],"diff":4},{"id":"playground-14","kind":"see","text":"Crawl tunnel","sub":"It joins the slide just below the platform.","acts":[1,2,3],"diff":4},{"id":"playground-15","kind":"see","text":"Bone pile","sub":"At the slide’s exit, a heap of small bones, picked clean.","acts":[1,2,3],"diff":4},{"id":"playground-16","kind":"see","text":"Bell rope","sub":"Coiled around the top of the bell post, just out of reach from the platform.","acts":[1,2,3],"diff":4},{"id":"playground-17","kind":"see","text":"Pebbles","sub":"Around the base of the tower.","acts":[1,2,3],"diff":4},{"id":"playground-18","kind":"object","text":"Pebble","sub":"A smooth gray stone, about the size of a thumbnail.","acts":[1,2,3],"diff":4},{"id":"playground-19","kind":"danger","text":"Reach the rope.","sub":"After climbing the tower, a long stretch from the platform.","acts":[1,2,3],"diff":2},{"id":"playground-1a","kind":"danger","text":"Escape the slide.","sub":"Climb back up.","acts":[1,2,3],"diff":6},{"id":"playground-1b","kind":"interact","text":"Splintered stump","sub":"The wooden tower is snapped off a meter above the ground, and the slide is gone.","acts":[3],"diff":4}],"desc":"A wooden play tower beside a red spiral slide. Inside the slide, a sour, swampy smell drifts out of it."},{"id":"playground-1c","name":"Gate","items":[{"id":"playground-1d","kind":"see","text":"Gate","sub":"Tall iron bars, about 4 meters high, topped with spikes. The High School shows dimly through the bars.","acts":[1,2,3],"diff":4},{"id":"playground-1e","kind":"see","text":"Bolt","sub":"A heavy iron bolt holds the gate shut.","acts":[1,2,3],"diff":4},{"id":"playground-1f","kind":"see","text":"Bell mechanism","sub":"A chain runs from the bolt, up the gate post, over a pulley and into the bell’s yoke. If the bell swings, the chain pulls the bolt.","acts":[1,2,3],"diff":4},{"id":"playground-1g","kind":"see","text":"Bell","sub":"A big brass school bell on top of the post, about 5 meters up.","acts":[1,2,3],"diff":4},{"id":"playground-1h","kind":"see","text":"Play Tower","sub":"Right beside the gate.","acts":[1,2,3],"diff":4},{"id":"playground-1i","kind":"interact","text":"Ring the bell","sub":"The bell clangs, the chain pulls the bolt, and the gate swings open. Every part of Jungle Jim wakes at once and comes for whoever is closest.","acts":[1,2,3],"diff":4},{"id":"playground-1j","kind":"danger","text":"Climb the gate","sub":"The spikes and the height.","acts":[1,2,3],"diff":10},{"id":"playground-1k","kind":"danger","text":"Shoot the bell.","sub":"With the slingshot and a pebble, from the ground.","acts":[1,2,3],"diff":4},{"id":"playground-1l","kind":"danger","text":"Escape Jungle Jim.","sub":"While all of Jim attacks.","acts":[1,2,3],"diff":8},{"id":"playground-1m","kind":"interact","text":"Torn gate","sub":"The iron bars are bent outward and ripped off one hinge, with green paint scraped along them. The bell lies cracked on the ground.","acts":[3],"diff":4}],"desc":"Tall iron bars at the far end of the playground, with a brass bell high on the post. A cold wind blows through the bars. The chain on the post clinks softly with every gust."}],"desc":"An empty school playground under a black sky, its equipment bright and freshly painted. The air is cold and smells of wet sand, paint and something sour. Chains creak.","nightmare":"Jungle Jim","crashDesc":"Wake up in the slide, being digested by Jungle Jim. Come out of it Raw (skin is red, tight and stinging, rinse with water or wait it out).","starts":["c8"],"x":40,"y":1560},{"id":"safe-house","name":"The Safe House","subs":[{"id":"safe-house-0","name":"(#1) Clock room","items":[{"id":"safe-house-1","kind":"see","text":"Ebony clock","sub":"Tall, with thirteen marks on the face. Both hands are stopped at the thirteenth, and it makes no ticking sound at all.","acts":[1,2,3],"diff":4},{"id":"safe-house-2","kind":"interact","text":"Wind the clock","sub":"With the winding key from the attic, the hands creep past the thirteenth mark and the clock strikes. The iron plates draw back from every window and the front door, and the doors unlock.","acts":[1,2,3],"diff":4},{"id":"safe-house-3","kind":"see","text":"Red windows","sub":"Iron plates sit flush over the glass, and a faint red tint lies across the floor.","acts":[1,2,3],"diff":4},{"id":"safe-house-4","kind":"see","text":"Brass rods","sub":"Thin rods run from every wall into the base of the clock’s case, the same rods seen at the front door and the windows.","acts":[1,2,3],"diff":4},{"id":"safe-house-5","kind":"see","text":"Vigil chair","sub":"A single high-backed chair facing the clock, worn smooth on the arms.","acts":[1,2,3],"diff":4},{"id":"safe-house-6","kind":"talk","text":"Madeline","sub":"A pale, thin old woman in black lace, seated in the chair.","acts":[1,2,3],"diff":4,"subjects":[{"id":"safe-house-7","name":"Clock","info":"It controls the house's security. Don't touch it, lest it messes with the security, which would be horrible."}]},{"id":"safe-house-8","kind":"see","text":"Blue door","sub":"To the Drawing Room.","acts":[1,2,3],"diff":4}],"desc":"A black-draped room lit by a dull red glow, with a towering ebony clock at its center. The room is utterly silent, with no ticking at all."},{"id":"safe-house-9","name":"(#2) Needlework Room","items":[{"id":"safe-house-a","kind":"see","text":"Mending basket","sub":"A wicker basket piled with torn linens, socks and collars waiting to be repaired.","acts":[1,2,3],"diff":4},{"id":"safe-house-b","kind":"see","text":"Sewing table","sub":"A low walnut table with a tray of pins, needles and spools of thread in every color.","acts":[1,2,3],"diff":4},{"id":"safe-house-c","kind":"see","text":"Tablecloth","sub":"A huge unfinished lace tablecloth draped over a frame, with a few square meters still to go.","acts":[1,2,3],"diff":4},{"id":"safe-house-d","kind":"object","text":"Embroidery scissors","sub":"Gilt handles and a sharp point, about 10 centimeters long.","acts":[1,2,3],"diff":4},{"id":"safe-house-e","kind":"object","text":"Silk thread and needle","sub":"A spool of about 30 meters of thin, strong thread, with needle.","acts":[1,2,3],"diff":4},{"id":"safe-house-f","kind":"talk","text":"Berenice","sub":"A small, neat woman in violet, stitching without looking up.","acts":[1,2,3],"diff":4,"subjects":[{"id":"safe-house-g","name":"Tablecloth","info":"She has been making it for years, and it is not done yet."}]},{"id":"safe-house-h","kind":"see","text":"Windows","sub":"Riveted plates sit flush over the glass.","acts":[1,2,3],"diff":4},{"id":"safe-house-i","kind":"see","text":"Blue door","sub":"To the Drawing Room.","acts":[1,2,3],"diff":4}],"desc":"A quiet room for sewing and mending. Spools of thread in every color crowd the tables, and a huge lace tablecloth stretches across a frame."},{"id":"safe-house-j","name":"(#3) Music room","items":[{"id":"safe-house-k","kind":"see","text":"Grand piano","sub":"Black lacquer, with the lid closed and a cloth draped over the keys.","acts":[1,2,3],"diff":4},{"id":"safe-house-l","kind":"see","text":"Harp","sub":"Tall and gilded, with one string cut and curled.","acts":[1,2,3],"diff":4},{"id":"safe-house-m","kind":"see","text":"Windows","sub":"Riveted plates sit flush over the glass.","acts":[1,2,3],"diff":4},{"id":"safe-house-n","kind":"see","text":"Chandelier","sub":"Crystal, hung over the room, with the candles unlit.","acts":[1,2,3],"diff":4},{"id":"safe-house-o","kind":"talk","text":"Ligeia","sub":"A tall, white-haired woman in a pale gown, seated at the harp.","acts":[1,2,3],"diff":4,"subjects":[{"id":"safe-house-p","name":"Music","info":"All the instruments are out of tune and in dire need of repair. Whenever she plays any, it upsets the Duchess. To be fair, it does sound horrible."}]},{"id":"safe-house-q","kind":"see","text":"Blue door","sub":"To the drawing room.","acts":[1,2,3],"diff":4}],"desc":"A pale, high-ceilinged room set aside for music, with a piano and harp at its center."},{"id":"safe-house-r","name":"(#4) Card room","items":[{"id":"safe-house-s","kind":"see","text":"Whist table","sub":"Green baize over a round table, with four chairs and a hand left half-played.","acts":[1,2,3],"diff":4},{"id":"safe-house-t","kind":"talk","text":"Morella","sub":"A sharp-eyed woman in orange silk, bored.","acts":[1,2,3],"diff":4,"subjects":[{"id":"safe-house-u","name":"Play","info":"She'd like to play a game of whist. That said, you'd need two more players. Most of the other ladies are too stuck-up to enjoy a game of cards, but they may have a chance persuading Lady Annabel and Ulalume."}]},{"id":"safe-house-v","kind":"object","text":"Deck of cards","sub":"Fifty-two worn cards, soft at the edges.","acts":[1,2,3],"diff":4},{"id":"safe-house-w","kind":"object","text":"Coin dish","sub":"A dozen copper pennies in a china dish.","acts":[1,2,3],"diff":4},{"id":"safe-house-x","kind":"interact","text":"Gather a table","sub":"After finding two more people, all will place a few coins of copper in the dish. They will then suggest each place something else of value, to make things interesting. They won't let the protagonist play without a bet.","acts":[1,2,3],"diff":4},{"id":"safe-house-y","kind":"danger","text":"Win a hand of whist","sub":"If they win, they get the two opponent's bets; Morella gives her smelling salts, Ulalume gives her sherry flask, and Annabel gives her pocket watch. No matter what, the losers will call the winners cheaters and leave.","acts":[1,2,3],"diff":4},{"id":"safe-house-z","kind":"object","text":"Pocket watch","sub":"A nice silver watch, stopped at the 13th hour.","acts":[1,2,3],"diff":4},{"id":"safe-house-10","kind":"object","text":"Sherry flask","sub":"A small silver flask of pale sherry.","acts":[1,2,3],"diff":4},{"id":"safe-house-11","kind":"object","text":"Smelling salts","sub":"A small cut-glass bottle. One sniff snaps a person out of a faint or a daze.","acts":[1,2,3],"diff":4},{"id":"safe-house-12","kind":"see","text":"Windows","sub":"Riveted plates sit flush over the glass.","acts":[1,2,3],"diff":4},{"id":"safe-house-13","kind":"see","text":"Sideboard","sub":"A dark wooden cabinet holding decanters, glasses and a silver cigar box.","acts":[1,2,3],"diff":4},{"id":"safe-house-14","kind":"see","text":"Blue door","sub":"To the drawing room.","acts":[1,2,3],"diff":4}],"desc":"A cozy parlor kept for card games, glowing orange from the lamp above the table."},{"id":"safe-house-15","name":"(#5) Conservatory","items":[{"id":"safe-house-16","kind":"see","text":"Potted plants","sub":"Ferns, small citrus trees and climbing vines in clay pots, all well tended.","acts":[1,2,3],"diff":4},{"id":"safe-house-17","kind":"see","text":"Windows","sub":"Riveted plates sit flush over the glass.","acts":[1,2,3],"diff":4},{"id":"safe-house-18","kind":"see","text":"Potting bench","sub":"A long wooden bench strewn with soil, twine and a few tools.","acts":[1,2,3],"diff":4},{"id":"safe-house-19","kind":"object","text":"Mallet","sub":"Wood, about 40 centimeters long, with a heavy head.","acts":[1,2,3],"diff":4},{"id":"safe-house-1a","kind":"object","text":"Pruning shears","sub":"Steel, about 20 centimeters long, with red-painted handles.","acts":[1,2,3],"diff":4},{"id":"safe-house-1b","kind":"object","text":"Watering can","sub":"Galvanized, with a long spout. It holds about four liters of water.","acts":[1,2,3],"diff":4},{"id":"safe-house-1c","kind":"object","text":"Garden twine","sub":"About 20 meters of rough cord on a wooden spool.","acts":[1,2,3],"diff":4},{"id":"safe-house-1d","kind":"talk","text":"Eleonora","sub":"A stout woman in green gloves, without a speck of dirt over her dress.","acts":[1,2,3],"diff":4,"subjects":[{"id":"safe-house-1e","name":"Plants","info":"She prefers tending to the plants then socializing with the others, as Duchess and the others can be quite thorny."}]},{"id":"safe-house-1f","kind":"see","text":"Blue door","sub":"To the drawing room.","acts":[1,2,3],"diff":4}],"desc":"A greenhouse-like room where the household grows plants indoors. Ferns and citrus trees crowd the air with a damp, earthy smell, and the warm air feels heavy with moisture."},{"id":"safe-house-1g","name":"(#6) Library","items":[{"id":"safe-house-1h","kind":"see","text":"Bookshelves","sub":"Floor-to-ceiling shelves packed with leather-bound volumes, with a rolling ladder on a brass rail.","acts":[1,2,3],"diff":4},{"id":"safe-house-1i","kind":"see","text":"Windows","sub":"Riveted plates sit flush over the glass.","acts":[1,2,3],"diff":4},{"id":"safe-house-1j","kind":"see","text":"Lectern","sub":"A wooden stand by the far wall, holding a thick, dusty book.","acts":[1,2,3],"diff":4},{"id":"safe-house-1k","kind":"interact","text":"House manual","sub":"It explains that the iron plates are driven by the house's clock, and remove themselves automatically when the hour passes.","acts":[1,2,3],"diff":4},{"id":"safe-house-1l","kind":"talk","text":"Lenore","sub":"A quiet woman in lavender, sitting at a writing desk with a stack of letters.","acts":[1,2,3],"diff":4,"subjects":[{"id":"safe-house-1m","name":"Letters","info":"She wants to write a letter to the Duchess to thank her for inviting her, but she can't quite find the right wording."}]},{"id":"safe-house-1n","kind":"see","text":"Letters","sub":"A mound of discarded drafts, each with only a few lines past the opening greeting, crossed and thrown out.","acts":[1,2,3],"diff":4},{"id":"safe-house-1o","kind":"see","text":"Blue door","sub":"To the drawing room","acts":[1,2,3],"diff":4}],"desc":"A hushed library with purple wallpaper and floor-to-ceiling shelves, lit by green-shaded lamps. The air smells of old paper, leather and ink."},{"id":"safe-house-1p","name":"(#7) Drawing room","items":[{"id":"safe-house-1q","kind":"see","text":"Windows","sub":"Riveted plates sit flush over the glass.","acts":[1,2,3],"diff":4},{"id":"safe-house-1r","kind":"see","text":"Tea service","sub":"Porcelain cups for a dozen, kept warm on a silver tray.","acts":[1,2,3],"diff":4},{"id":"safe-house-1s","kind":"object","text":"Hooked pole","sub":"Brass, about 3 meters long, with a hook at the tip.","acts":[1,2,3],"diff":4},{"id":"safe-house-1t","kind":"danger","text":"Sneak out the pole","sub":"It's not yours, and you shouldn't poke around in someone else's house.","acts":[1,2,3],"diff":4},{"id":"safe-house-1u","kind":"interact","text":"Greetings","sub":"The Duchess will greet any stranger in, as long as they behave appropriately. They'll ask how they got in, and won't mind any described lawful ways, and invite them to stay out the hour.","acts":[1,2],"diff":4},{"id":"safe-house-1v","kind":"talk","text":"Dowager Duchess Prospero","sub":"A broad, commanding woman in blue velvet, in her seventies.","acts":[1,2,3],"diff":4,"subjects":[{"id":"safe-house-1w","name":"Lockdown","info":"The house locks itself at the 13th hour and unlocks when it passes. It's to avoid the Nightmares that come out at this hour."},{"id":"safe-house-1x","name":"Front door","info":"The house locks it every 13th hour automatically, and unlocks it when it passes."},{"id":"safe-house-1y","name":"Knocking","info":"She hears nothing and insists the house is settling. If she sees something upsetting, she will be angry at whoever forced her to see it, and lock it \"out of mind\"."},{"id":"safe-house-1z","name":"Time","info":"They refuse to think something's wrong with time, and will say that time might feel so long because they're bored. Maybe they should do something to pass the time."}]},{"id":"safe-house-20","kind":"object","text":"Chatelaine keys","sub":"A silver ring on a long chain, hung with about thirty keys of every age. It opens every do","acts":[1,2,3],"diff":4},{"id":"safe-house-21","kind":"danger","text":"Find the right key","sub":"Every time, when using the Chatelaine keys.","acts":[1,2,3],"diff":2},{"id":"safe-house-22","kind":"danger","text":"Steal the keys","sub":"The Duchess will lock you away in a room if you do something like this.","acts":[1,2,3],"diff":6},{"id":"safe-house-23","kind":"talk","text":"Lady Annabel","sub":"A gentle old woman in pale blue silk, with a lace shawl and a faraway smile.","acts":[1,2,3],"diff":4,"subjects":[{"id":"safe-house-24","name":"Tea","info":"She offers a cup to anyone who comes near."},{"id":"safe-house-25","name":"House","info":"It is a lovely home, and she is happy to be safe in it."},{"id":"safe-house-26","name":"Hour","info":"It will pass soon."}]},{"id":"safe-house-27","kind":"talk","text":"Lady Ulalume","sub":"A thin, sharp-faced woman in dark blue, who sits where she can see the whole room.","acts":[1,2,3],"diff":4,"subjects":[{"id":"safe-house-28","name":"Strangers","info":"She asks where you came from, and she is suspicious of the answer. Who invited you? Well, it's not polite to go places uninvited, but you're safe here. Good for you."}]},{"id":"safe-house-29","kind":"interact","text":"Knocked doors","sub":"The Duchess locks each one, and refuses to open them back up, keeping the horrors out of mind.","acts":[1,2,3],"diff":4},{"id":"safe-house-2a","kind":"interact","text":"Knocked house","sub":"If let to its own accord, the Knocker will get to everyone in the house. When a body is inspected, baby birds will crawl out of the skull hole, and a swarm of Knockers will attack them out of the house.","acts":[3],"diff":4},{"id":"safe-house-2b","kind":"danger","text":"Survive the swarm.","sub":"A swarm of knockers, relentless until they're out of the house.","acts":[3],"diff":8},{"id":"safe-house-2c","kind":"see","text":"Blue door","sub":"To the Entrance Hall.","acts":[1,2,3],"diff":4},{"id":"safe-house-2d","kind":"see","text":"Black door","sub":"To the Clock Room.","acts":[1,2,3],"diff":4},{"id":"safe-house-2e","kind":"see","text":"Violet door","sub":"To the Needlework Room.","acts":[1,2,3],"diff":4},{"id":"safe-house-2f","kind":"see","text":"White door","sub":"To the Music Room.","acts":[1,2,3],"diff":4},{"id":"safe-house-2g","kind":"see","text":"Orange door","sub":"To the Card Room.","acts":[1,2,3],"diff":4},{"id":"safe-house-2h","kind":"see","text":"Green door","sub":"To the Conservatory.","acts":[1,2,3],"diff":4},{"id":"safe-house-2i","kind":"see","text":"Purple door","sub":"To the Library.","acts":[1,2,3],"diff":4}],"desc":"A grand sitting room with blue wallpaper.Velvet sofas and armchairs are grouped in circles, and the murmur of polite conversation fills the air. Every voice and clink of porcelain echoes off the high ceiling."},{"id":"safe-house-2j","name":"Entrance Hall","items":[{"id":"safe-house-2k","kind":"interact","text":"Phee's Arrival","sub":"Phee has stepped through a door that was not there before. It is gone now, and unbroken wallpaper covers the wall behind her.","acts":[1,2,3],"diff":4},{"id":"safe-house-2l","kind":"see","text":"Front door","sub":"Plated over with riveted iron, with no keyhole, handle or bolts. The plates sit flush against the frame.","acts":[1,2,3],"diff":4},{"id":"safe-house-2m","kind":"see","text":"Windows","sub":"Riveted plates sit flush over the glass.","acts":[1,2,3],"diff":4},{"id":"safe-house-2n","kind":"see","text":"Attic hatch","sub":"A square trapdoor in the ceiling, about 4 meters up. Its pull cord dangles just out of reach.","acts":[1,2,3],"diff":4},{"id":"safe-house-2o","kind":"interact","text":"Opening the attic","sub":"Requires something that can hook it down.","acts":[1,2,3],"diff":4},{"id":"safe-house-2p","kind":"see","text":"Blue door","sub":"To the Drawing room. Women's voices can be heard behind it.","acts":[1,2,3],"diff":4},{"id":"safe-house-2q","kind":"interact","text":"The Knocker","sub":"A red woodpecker about 60 centimeters tall, with a long, hooked iron-gray beak.","acts":[1,2,3],"diff":4},{"id":"safe-house-2r","kind":"interact","text":"Pecking order","sub":"Each time the Knocker knocks someone out, a knocking is first head, echoing in the hall. It starts from #1 to #7, targets rooms without the protagonist, skipping those rooms and returning after the cycle ends, but may be tricked if the protagonist hides or pretends not to see it.","acts":[2,3],"diff":4},{"id":"safe-house-2s","kind":"danger","text":"Kill the Knocker","sub":"Smashing it with something, a mallet perhaps.","acts":[1,2,3],"diff":4},{"id":"safe-house-2t","kind":"danger","text":"Catch the Knocker","sub":"With a cage. Easier if it thinks they don't see it.","acts":[1,2,3],"diff":6}],"desc":"A grand English manor hall with black-and-white marble floor. Oil lamps line the oak-paneled walls. The air smells of beeswax polish and lamp oil."},{"id":"safe-house-2u","name":"Attic","items":[{"id":"safe-house-2v","kind":"see","text":"Hatch ladder","sub":"A folding ladder leads down to the Entrance Hall.","acts":[1,2,3],"diff":4},{"id":"safe-house-2w","kind":"see","text":"Furniture","sub":"Dust sheets cover old furniture; dressers, wardrobes, and tall mirrors.","acts":[1,2,3],"diff":4},{"id":"safe-house-2x","kind":"danger","text":"Search the drawers","sub":"They contain a lot of old clothes, dishes, silverware and one drawer contains gears, screws, and the winding key.","acts":[1,2,3],"diff":2},{"id":"safe-house-2y","kind":"object","text":"Winding key","sub":"Black brass, about 12 centimeters long, with a square socket at one end.","acts":[1,2,3],"diff":4},{"id":"safe-house-2z","kind":"see","text":"Round window","sub":"Small and decorative, not reinforced. Looks out to the yard.","acts":[1,2,3],"diff":4},{"id":"safe-house-30","kind":"see","text":"Outside","sub":"Below, a neat green lawn stretches to the tree line. A big oak stands beside the house, with a wooden ladder lashed to its trunk. The dark forest begins just past the grass.","acts":[1,2,3],"diff":4},{"id":"safe-house-31","kind":"danger","text":"Break the window","sub":"With bare hands, can cause a cut.","acts":[1,2,3],"diff":2},{"id":"safe-house-32","kind":"danger","text":"Jump out the window","sub":"Dangerous, but doable.","acts":[1,2,3],"diff":6}],"desc":"A low, cramped attic under the sloping roof, with gray light at one end. The air is dry and stuffy and smells of mothballs and old wood."},{"id":"safe-house-33","name":"YARD","items":[{"id":"safe-house-34","kind":"see","text":"Lawn","sub":"A neat green lawn about 30 meters across, trimmed short.","acts":[1,2,3],"diff":4},{"id":"safe-house-35","kind":"see","text":"Manor front","sub":"A grand stone front. The front door seems locked, even though there are no locks.","acts":[1,2,3],"diff":4},{"id":"safe-house-36","kind":"interact","text":"Knock on the door","sub":"The Dowager Duchess answers from behind the door. She says she and her friends are locked inside safely and won't open the door until the 13th hour has passed.","acts":[1,2],"diff":4},{"id":"safe-house-37","kind":"see","text":"Windows","sub":"The multiple large windows of the manor are reinforced with steel plates from the inside.","acts":[1,2,3],"diff":4},{"id":"safe-house-38","kind":"see","text":"Round window","sub":"Small and decorative, high in the roof, the only window without iron plates.","acts":[1,2,3],"diff":4},{"id":"safe-house-39","kind":"danger","text":"Break the window","sub":"With bare hands it can cause a cut.","acts":[1,2,3],"diff":2},{"id":"safe-house-3a","kind":"see","text":"Oak tree","sub":"A big old oak beside the house, with a wooden ladder lashed to its trunk.","acts":[1,2,3],"diff":4},{"id":"safe-house-3b","kind":"object","text":"Birdcage","sub":"Brass, with a lockable door. Big enough for one bird.","acts":[1,2,3],"diff":4},{"id":"safe-house-3c","kind":"interact","text":"Move the ladder","sub":"Easily removed from the tree, high enough to reach the round window.","acts":[1,2,3],"diff":4},{"id":"safe-house-3d","kind":"see","text":"Into the woods","sub":"A trail leads from the edge of the lawn into the forest.","acts":[1,2,3],"diff":4}],"desc":"A great stone manor looms over a neat green lawn, with dark forest beyond. The air is cool and wind rustles the oak leaves."}],"boons":[{"id":"safe-house-3e","name":"Chatelaine keys","note":""}],"desc":"A great English manor. Iron plates cover every window. The air smells of beeswax and tea, and every footstep and whisper echoes back from tall ceilings.","nightmare":"The Knocker","crashDesc":"If the protagonist has been nosey, the ladies will tie them to a chair in the drawing room. The chair can still be moved, but one of the ladies (likely Ulalume) will be watching. It's best for everyone, they'll say, until the hour passes.","favText":"Chatelaine keys","starts":["c2"],"x":440,"y":1560},{"id":"theater","name":"The Theater","subs":[{"id":"theater-0","name":"Backstage","items":[{"id":"theater-1","kind":"interact","text":"Arriving","sub":"Jane comes to on the floor of the elevator, her head pounding. An hour has passed. She has Headache: loud noise and bright light make every roll harder until treated.","acts":[1],"diff":4},{"id":"theater-2","kind":"see","text":"Service elevator","sub":"An iron cage elevator with a folding gate, its button panel dark.","acts":[1,2,3],"diff":4},{"id":"theater-3","kind":"see","text":"Galvanic apparatus","sub":"A tall wooden cabinet of glass jars, copper coils and brass levers, humming. Thick cables run from it out to the Pit.","acts":[1,2,3],"diff":4},{"id":"theater-4","kind":"object","text":"Leyden jar","sub":"A glass jar lined with foil, holding one charge. Brings back someone from Crashing.","acts":[1,2,3],"diff":4},{"id":"theater-5","kind":"see","text":"Ropes and sandbags","sub":"The fly ropes for the curtain, tied off to a rail.","acts":[1,2,3],"diff":4},{"id":"theater-6","kind":"see","text":"Dead assistant","sub":"Young man in a white apron, slumped against the wall. His skull is caved in at the back, where the Stiff slammed it against the apparatus, and blood and gray matter crust his collar.","acts":[1,2,3],"diff":4},{"id":"theater-7","kind":"talk","text":"The Professor","sub":"A tall, gaunt showman in a bloodstained frock coat, with singed fingertips and a fixed smile. Polite, panicking, sweating through his collar.","acts":[1,2,3],"diff":4,"subjects":[{"id":"theater-8","name":"The show","info":"Galvanic marvels. Current through the dead, making them dance and sing. The Gallery adores it."},{"id":"theater-9","name":"The Stiff","info":"He wakes every 13th hour and throws a tantrum, then drops when it passes. This time the hour won’t pass."},{"id":"theater-a","name":"The Gallery","info":"“If they don’t like the show, they’ll tear us to pieces.”"},{"id":"theater-b","name":"Assistant","info":"Useless now. The rigging needs an intact brain to carry the current, and look at him."},{"id":"theater-c","name":"","info":""}]},{"id":"theater-d","kind":"talk","text":"Nip, the stagehand","sub":"A twitchy boy in a flat cap, who never stops coiling cable and won’t look at the Gallery.","acts":[1,2,3],"diff":4,"subjects":[{"id":"theater-e","name":"The Stiff","info":"He does this every night, but usually he drops after the hour passes."},{"id":"theater-f","name":"Levers","info":"Green makes him twitch, red makes him dance, the big one makes him sing."},{"id":"theater-g","name":"Assistant","info":"The assistant moves the clamps on the Stiff’s body during the act, onto the right nerves, at the right moment, to make the right limb jump. That takes a medical hand, which Nip doesn’t have, and which Jane, a nurse, does."}]}],"desc":"A cramped, dim backstage crowded with ropes, crates and humming machinery. The air smells of ozone, hot copper and formaldehyde. Beyond the curtain, a crowd mutters and rustles, waiting."},{"id":"theater-h","name":"Stiff's Trailer","items":[{"id":"theater-i","kind":"see","text":"Caravan","sub":"A showman’s wagon, painted with faded gold stars and THE AMAZING ANIMATED STIFF in curling letters.","acts":[1,2,3],"diff":4},{"id":"theater-j","kind":"interact","text":"Locked door","sub":"Bolted from inside. A cracked window shows candlelight.","acts":[1,2,3],"diff":4},{"id":"theater-k","kind":"see","text":"The Stiff","sub":"Through the window: a bloated corpse wrapped in a sheet, stitched at the chest, with brass electrodes bolted to his temples. He lounges on a velvet couch and sulks.","acts":[1,2,3],"diff":4},{"id":"theater-l","kind":"talk","text":"The Stiff","sub":"A vain, sulking corpse with a fruity, theatrical voice. He talks through the door. Every time a demand is met, he thinks of another, out loud, as if he’d always wanted it.","acts":[1,2,3],"diff":4,"subjects":[{"id":"theater-m","name":"The show","info":"He’s done with it. It degrades him. He’s an artist."},{"id":"theater-n","name":"1: Top billing","info":"His name, big, on the playbill. Met with the greasepaint in the Dressing Room. It changes nothing on stage, only his ego."},{"id":"theater-o","name":"2: Dressing gown","info":"He’ll perform in his silk gown. Met by fetching it from his trailer. It hides some of the stitches."},{"id":"theater-p","name":"3: Dim the lamp","info":"The light is unflattering. Met by lowering the Pit’s lamp from Backstage. The Gallery can barely see the gore."},{"id":"theater-q","name":"4: His own song","info":"A mournful ballad instead of the Professor’s bawdy number. Met by swapping the sheet music from the Dressing Room. The finale becomes a dirge."},{"id":"theater-r","name":"5: Cut the dance","info":"Dancing is beneath an artist. Met by telling Nip to strike the dance cue. The middle of the show is gone."},{"id":"theater-s","name":"6: Less current","info":"“It burns.” Met by turning the apparatus down to half. He barely twitches, and the whole show goes limp."}]},{"id":"theater-t","kind":"danger","text":"Convince the Stiff.","sub":"Can’t be rolled at 0 demands met. 1 demand: (10). 2: (8). 3: (6). 4: (4). 5: (2). At 6 demands, he can’t think of anything else and does the show.","acts":[1,2,3],"diff":10}],"desc":"A painted showman’s caravan in the shadowy wings, its window glowing with candlelight. The air around it smells of lilies, wax and something rotten underneath."},{"id":"theater-u","name":"Dressing Room","items":[{"id":"theater-v","kind":"see","text":"Mirror table","sub":"A vanity ringed with bare bulbs, its mirror cracked across the middle. Pots of greasepaint and powder crowd the top.","acts":[1,2,3],"diff":4},{"id":"theater-w","kind":"object","text":"Greasepaint","sub":"A stick of red greasepaint.","acts":[1,2,3],"diff":4},{"id":"theater-x","kind":"see","text":"Playbill","sub":"A poster on the wall: PROFESSOR CRANE’S GALVANIC MARVELS, with “featuring the Stiff” in tiny letters at the bottom.","acts":[1,2,3],"diff":4},{"id":"theater-y","kind":"see","text":"Dressing gown","sub":"A silk dressing gown in faded burgundy, hanging on a hook, embroidered with a gold S.","acts":[1,2,3],"diff":4},{"id":"theater-z","kind":"object","text":"Dressing gown","sub":"Silk, burgundy, with a gold S.","acts":[1,2,3],"diff":4},{"id":"theater-10","kind":"see","text":"Sheet music","sub":"A stack of yellowed sheets on a chair. On top, a ballad written in a looping, shaky hand, titled Lament for a Gentleman.","acts":[1,2,3],"diff":4},{"id":"theater-11","kind":"object","text":"Ballad sheet","sub":"Lament for a Gentleman, in the Stiff’s own hand. Slow, mournful and four pages long.","acts":[1,2,3],"diff":4},{"id":"theater-12","kind":"see","text":"Medical bag","sub":"The Professor’s black leather bag, open on the floor, with brown glass bottles inside.","acts":[1,2,3],"diff":4},{"id":"theater-13","kind":"object","text":"Painkillers","sub":"A brown glass bottle of tablets.","acts":[1,2,3],"diff":4},{"id":"theater-14","kind":"see","text":"Rack of costumes","sub":"Sequined jackets, a top hat and a white apron.","acts":[1,2,3],"diff":4}],"desc":"A cramped dressing room lit by a ring of bare bulbs. The air is thick with face powder, stale sweat and mothballs."},{"id":"theater-15","name":"The Pit","items":[{"id":"theater-16","kind":"see","text":"Operating table","sub":"A steel table in the middle of a round sawdust pit, with leather straps and brass cable clamps.","acts":[1,2,3],"diff":4},{"id":"theater-17","kind":"danger","text":"Finish the show","sub":"0 demands met: no roll, the show succeeds. 1: (2). 2: (4). 3: (6). 4: (8). 5: (10). 6: the show bombs.","acts":[1,2,3],"diff":2},{"id":"theater-18","kind":"interact","text":"The show","sub":"(Once the Stiff agrees.) The Stiff is strapped to the table. Jane, as the assistant, moves the clamps and works the levers, and the Stiff twitches, dances and sings for the crowd.","acts":[1,2,3],"diff":4},{"id":"theater-19","kind":"danger","text":"Get off the table.","sub":"Talk the Professor out of it, or work the straps loose while he isn’t looking.","acts":[1,2,3],"diff":4},{"id":"theater-1a","kind":"see","text":"Hanging lamp","sub":"A big surgical lamp on a chain above the table, blazing white.","acts":[1,2,3],"diff":4},{"id":"theater-1b","kind":"see","text":"Music stand","sub":"At the edge of the pit, holding the Professor’s song: The Galvanic Gallop, its margins scribbled with cues.","acts":[1,2,3],"diff":4},{"id":"theater-1c","kind":"see","text":"Galvanic cables","sub":"Thick, black and fraying, running from the table to the wings.","acts":[1,2,3],"diff":4},{"id":"theater-1d","kind":"see","text":"Stained sawdust","sub":"Dark patches spread under the table.","acts":[1,2,3],"diff":4},{"id":"theater-1e","kind":"see","text":"The Gallery","sub":"Steep tiers of wooden benches rising on every side, packed with figures in evening dress. Each holds opera glasses to their face and never lowers them.","acts":[1,2,3],"diff":4},{"id":"theater-1f","kind":"interact","text":"The Gallery’s mood","sub":"They applaud, slowly and in unison. They mutter and bicker in a language that sounds almost familiar.","acts":[1,2,3],"diff":4},{"id":"theater-1g","kind":"object","text":"The Galvanic Gallop","sub":"The Professor’s sheet music. Loud, bawdy and two pages long.","acts":[1,2,3],"diff":4},{"id":"theater-1h","kind":"interact","text":"Curtain","sub":"When the show ends, good or bad, the curtain falls and the Foyer doors unlock.","acts":[1,2,3],"diff":4},{"id":"theater-1i","kind":"interact","text":"Bad show","sub":"(If the show fails.) The Gallery produces a loud, disapproving moan all at once, and starts climbing down the tiers.","acts":[1,2,3],"diff":4},{"id":"theater-1j","kind":"danger","text":"Escape the Gallery.","sub":"After a bad show. Out through the Foyer before they reach you.","acts":[1,2,3],"diff":8},{"id":"theater-1k","kind":"interact","text":"Torn performers","sub":"The Professor and Nip lie in pieces across the pit, pulled apart rather than cut. An arm still in its frock-coat sleeve hangs from the lamp chain, dripping onto the table. Loops of gut trail through the sawdust toward the benches, and the sawdust is soaked black. Nip’s flat cap sits upright in the middle of it all, with part of his scalp still inside. The smell of opened bodies is thick in the hot air, and flies have already found them.","acts":[3],"diff":4}],"desc":"A round sawdust pit under a blazing surgical lamp, ringed by steep tiers packed with silent watchers. The air is hot and smells of carbolic, old blood and stale perfume."},{"id":"theater-1l","name":"The Foyer","items":[{"id":"theater-1m","kind":"see","text":"Foyer","sub":"A tiled hall with a high ceiling, gas lamps and peeling green paint, like a hospital entrance. A faded sign over the doors reads WARD 13.","acts":[1,2,3],"diff":4},{"id":"theater-1n","kind":"talk","text":"The Usher","sub":"A stiff man in a tight burgundy uniform, buttoned to the throat, standing in front of the doors with his hands folded.","acts":[1,2,3],"diff":4,"subjects":[{"id":"theater-1o","name":"Leaving","info":"Nobody leaves during a show. Intermission counts."},{"id":"theater-1p","name":"Show","info":"It will resume shortly."}]},{"id":"theater-1q","kind":"see","text":"Front doors","sub":"Heavy double doors with frosted glass, chained shut. Streetlights from District 13 glow faintly through them.","acts":[1,2,3],"diff":4},{"id":"theater-1r","kind":"see","text":"Intermission bar","sub":"A small wooden bar with a tea urn, a tray of stale sandwiches and rows of clean glasses.","acts":[1,2,3],"diff":4},{"id":"theater-1s","kind":"see","text":"Programmes","sub":"A stack of printed programmes on a side table.","acts":[1,2,3],"diff":4},{"id":"theater-1t","kind":"object","text":"Programme","sub":"PROFESSOR CRANE’S GALVANIC MARVELS. It lists: the Twitch, The Dance, The Galvanic Gallop.","acts":[1,2,3],"diff":4},{"id":"theater-1u","kind":"see","text":"Hospital bench","sub":"A long wooden bench along the wall, the kind found in a waiting room.","acts":[1,2,3],"diff":4},{"id":"theater-1v","kind":"danger","text":"Slip past the Usher.","sub":"During the show. The doors are chained, and he’s always there.","acts":[1,2,3],"diff":10}],"desc":"A cold, tiled hall that still feels like a hospital, lit by hissing gas lamps. The air smells of disinfectant, stewed tea and old cigarettes."}],"boons":[{"id":"theater-1w","name":"Leyden jar","note":""}],"desc":"An old hospital wing in District 13, converted into a theater for a single, gruesome show. Inside, it smells of carbolic, ozone and rot.","nightmare":"The Gallery","crashDesc":"Jane comes to strapped to the operating table, under the blazing lamp. Brass electrodes are screwed into both temples. A row of fresh stitches runs down her chest, and the Professor is threading the next cable, humming. He tells her to hold still. (Wired: screwed skull, Cut: incision in process)","favText":"Leyden jar","starts":["c7"],"x":840,"y":1560},{"id":"warrens","name":"The Warrens","subs":[{"id":"warrens-0","name":"Locke, Stocke, and Berell","items":[{"id":"warrens-1","kind":"talk","text":"Example NPC","sub":"a","acts":[1,2],"subjects":[{"id":"warrens-2","name":"Example","info":"Information that they know"},{"id":"warrens-3","name":"test","info":"testests"}]},{"id":"warrens-4","kind":"object","text":"Wine Bottle","sub":"Glass. Not a drop of wine left, but still smells like it.","acts":[1,2,3]}],"desc":"Example text."},{"id":"warrens-5","name":"The Nightly Revealer","items":[]}],"boons":[{"id":"warrens-6","name":"Fenwick Quire","note":"By bringing him the King's True Name, he will write an article about his death."}],"desc":"A long description of this place. A long description of this place. A long description of this place. A long description of this place. A long description of this place. A long description of this place. A long description of this place. A long description of this place. A long description of this place. A long description of this place. A long description of this place. A long description of this place.","nightmare":"Fenwick Quire","x":240,"y":430},{"id":"wax-works","name":"The Wax Works","subs":[{"id":"wax-works-0","name":"The Drains","items":[]},{"id":"wax-works-1","name":"The Mint","items":[]}],"nightmare":"The Snuffers","x":1240,"y":1560},{"id":"wild-wood","name":"The Wild Wood","subs":[{"id":"wild-wood-0","name":"Riverbank","items":[{"id":"wild-wood-1","kind":"see","text":"River","sub":"Shallow and fast, running downstream toward the Hoggery, loud over a stretch of rapids.","acts":[1,2,3],"diff":4},{"id":"wild-wood-2","kind":"see","text":"Dam","sub":"A half-built dam of branches, mud and drowned people, tangled together with limp arms and legs sticking out.","acts":[1,2,3],"diff":4},{"id":"wild-wood-3","kind":"object","text":"Jam jar","sub":"A glass jar with a cork. Still has old jam inside.","acts":[1,2,3],"diff":4},{"id":"wild-wood-4","kind":"danger","text":"Catch the flies.","sub":"With the jar.","acts":[1,2,3],"diff":2},{"id":"wild-wood-5","kind":"interact","text":"Finish the dam","sub":"The river drains to nothing. A dry bed leads to the Hoggery, with no swimming or canoe needed.","acts":[1,2,3],"diff":4},{"id":"wild-wood-6","kind":"interact","text":"Conclusion","sub":"“And from that day on, the Fox took only what was freely given, and the Beaver’s dam was finished, and the river ran quiet. The Fox had a very full supper that night, which we needn’t discuss. For what is not yours is not yours to take.”","acts":[1,2,3],"diff":4},{"id":"wild-wood-7","kind":"danger","text":"Run the rapids","sub":"(Before the dam is done.) Downstream to the Hoggery. Swimming is (8, Extreme).","acts":[1,2,3],"diff":4},{"id":"wild-wood-8","kind":"see","text":"Flies","sub":"A droning cloud above the dam.","acts":[1,2,3],"diff":4},{"id":"wild-wood-9","kind":"talk","text":"Beaver","sub":"A stout brown beaver in a tiny waistcoat, slapping mud with his tail and muttering measurements. Brisk, worried and proud of his work.","acts":[1,2,3],"diff":4,"subjects":[{"id":"wild-wood-a","name":"Dam","info":"Three \"logs\" short. It will make the finest pond in the woods."},{"id":"wild-wood-b","name":"Logs","info":"The Fox keeps taking them. “Rotten manners.”"}]},{"id":"wild-wood-c","kind":"see","text":"Glade path","sub":"Back to the Glade.","acts":[1,2,3],"diff":4}],"desc":"A sunny riverbank in a storybook wood, bright and green, with the river tumbling past. A mud-and-rot smell hangs under the sweetness of wild flowers. Flies drone, and the river hisses over the rapids."},{"id":"wild-wood-d","name":"Glade","items":[{"id":"wild-wood-e","kind":"see","text":"Clearing","sub":"A sunlit circle of soft grass with a ring of red toadstools.","acts":[1,2,3],"diff":4},{"id":"wild-wood-f","kind":"see","text":"Great oak","sub":"Huge, with a crown that climbs out of sight, up to the rooftops.","acts":[1,2,3],"diff":4},{"id":"wild-wood-g","kind":"interact","text":"Storybook","sub":"A huge book open on a mossy stump, with three blank pages. An illustration fades in on each when a lesson is learned.","acts":[1,2,3],"diff":4},{"id":"wild-wood-h","kind":"interact","text":"Omnipotent Third Person","sub":"A warm, unhurried voice from everywhere, describing everything in the third person. Whatever it says of someone, they do. A vulgar, nasty or mean protagonist is narrated into politeness.","acts":[1,2,3],"diff":4},{"id":"wild-wood-i","kind":"interact","text":"Conclusion (All 3 Finished)","sub":"“And so the Wild Wood was at peace, and every creature knew its place, and nothing unpleasant ever happened again. And they all lived happily ever after. Or very nearly all.”","acts":[1,2,3],"diff":4},{"id":"wild-wood-j","kind":"interact","text":"Plug your ears","sub":"With cotton from the Meadow, the voice can’t reach you.","acts":[1,2,3],"diff":4},{"id":"wild-wood-k","kind":"see","text":"Signposts","sub":"Wooden arrows pointing in every direction.","acts":[1,2,3],"diff":4},{"id":"wild-wood-l","kind":"interact","text":"Paths","sub":"To the Riverbank, Fox’s Den, Meadow, Field, Edge and Tunnel.","acts":[1,2,3],"diff":4}],"desc":"A sunlit clearing of soft grass and red toadstools, with a great oak at its edge. It smells of honey and clover, and the air is peaceful."},{"id":"wild-wood-m","name":"Fox's Den","items":[{"id":"wild-wood-n","kind":"see","text":"Den","sub":"A cozy hollow under mossy roots, with a round green door, a doormat reading WELCOME and warm lamplight inside.","acts":[1,2,3],"diff":4},{"id":"wild-wood-o","kind":"see","text":"Tea table","sub":"Laid for one, with a lace cloth, a silver teapot, a bone-china cup and a napkin ring.","acts":[1,2,3],"diff":4},{"id":"wild-wood-p","kind":"see","text":"Bodies","sub":"Three bodies stacked at the back, neatly, with half-gnawed limbs. They're placed next to a wood furnace. One carries the Exchequer’s Keys.","acts":[1,2,3],"diff":4},{"id":"wild-wood-q","kind":"object","text":"Exchequer’s Keys","sub":"A heavy brass ring on a damp leather cord, with the label \"COFFER\".","acts":[1,2,3],"diff":4},{"id":"wild-wood-r","kind":"talk","text":"Fox","sub":"A sleek orange fox in a waistcoat, with a napkin tucked in his collar. Silky, charming and in no hurry. He talks about food a great deal.","acts":[1,2,3],"diff":4,"subjects":[{"id":"wild-wood-s","name":"Bodies","info":"“Borrowed from the Beaver, he has so many, why does it matter if I take some for myself. Terribly rude of him to mind.”"},{"id":"wild-wood-t","name":"Snack","info":"Fetch me something nicer to nibble, and the bodies are yours."},{"id":"wild-wood-u","name":"Rabbit","info":"A plump fellow in the meadow. Lovely manners. Rather out of reach."},{"id":"wild-wood-v","name":"Snake","info":"Stringy. Though I’d take it in a pinch."}]},{"id":"wild-wood-w","kind":"interact","text":"Give him a snack","sub":"Hand over the Rabbit or the Snake. He eats it and nods at the stack. Take the bodies, and the Narrator gives the Beaver-and-Fox moral once the dam is finished.","acts":[1,2,3],"diff":4},{"id":"wild-wood-x","kind":"see","text":"Glade path","sub":"Back to the Glade.","acts":[1,2,3],"diff":4}],"desc":"A snug, lamplit burrow under mossy roots, warm and neat, with a table laid for tea. It smells of woodsmoke and roast meat, with something sweetly rotten underneath."},{"id":"wild-wood-y","name":"Meadow","items":[{"id":"wild-wood-z","kind":"see","text":"Meadow","sub":"A rolling field of wildflowers and clover, loud with bees, ringed by a low hedge.","acts":[1,2,3],"diff":4},{"id":"wild-wood-10","kind":"talk","text":"Rabbit","sub":"A plump, trembling rabbit in a little blue jacket, frozen at the mouth of his burrow with his ears flat. Timid, polite and out of breath.","acts":[1,2,3],"diff":4,"subjects":[{"id":"wild-wood-11","name":"Snake","info":"“He wants to eat me! He’s been circling all morning.”"},{"id":"wild-wood-12","name":"Fox","info":"“Oh, the Fox is lovely. He asked me to tea.”"}]},{"id":"wild-wood-13","kind":"danger","text":"Coax the Rabbit.","sub":"Out of his burrow, easier without a snake.","acts":[1,2,3],"diff":4},{"id":"wild-wood-14","kind":"talk","text":"Snake","sub":"A long green snake, coiled in the clover with a tongue flicking, eyeing the Rabbit. Lazy, sly and rather sleepy.","acts":[1,2,3],"diff":4,"subjects":[{"id":"wild-wood-15","name":"Hunger","info":"“I’m only hungry. It’s only natural.”"},{"id":"wild-wood-16","name":"Rabbit","info":"“A very fine rabbit.”"}]},{"id":"wild-wood-17","kind":"danger","text":"Chase off the Snake.","sub":"It slithers away into the hedge.","acts":[1,2,3],"diff":4},{"id":"wild-wood-18","kind":"talk","text":"Crow","sub":"A glossy black crow on a fence post, singing terribly and loudly, with his feathers puffed up. Vain, hurt and loud.","acts":[1,2,3],"diff":4,"subjects":[{"id":"wild-wood-19","name":"Singing","info":"“The finest voice in the wood.”"},{"id":"wild-wood-1a","name":"Bear","info":"“He called it a screech. What a bully. What does he know about singing?”"},{"id":"wild-wood-1b","name":"Compliments","info":"\"Do go on.\""}]},{"id":"wild-wood-1c","kind":"danger","text":"Flatter the Crow.","sub":"Easy.","acts":[1,2,3],"diff":2},{"id":"wild-wood-1d","kind":"see","text":"Cotton plants","sub":"A row of fluffy white cotton bushes along the hedge.","acts":[1,2,3],"diff":4},{"id":"wild-wood-1e","kind":"see","text":"Hedge gap","sub":"A gap in the hedge opens onto a manor’s front lawn (the Safe House).","acts":[1,2,3],"diff":4},{"id":"wild-wood-1f","kind":"see","text":"Glade path","sub":"Back to the Glade.","acts":[1,2,3],"diff":4},{"id":"wild-wood-1g","kind":"object","text":"Cotton","sub":"Soft wads of cotton that can be rolled into balls.","acts":[1,2,3],"diff":4},{"id":"wild-wood-1h","kind":"interact","text":"Win over the Crow.","sub":"Flatter him, or agree he was wronged. He'll help.","acts":[1,2,3],"diff":4}],"desc":"A sunny meadow thick with clover and wildflowers, humming with bees. The air is sweet with honey and cut grass, and warm sun lies on the back of the neck. A terrible, off-key song floats across the grass."},{"id":"wild-wood-1i","name":"Field","items":[{"id":"wild-wood-1j","kind":"see","text":"Field","sub":"A golden field of tall grass, fenced all round, with neat piles of straight sticks and branches heaped along the rows.","acts":[1,2,3],"diff":4},{"id":"wild-wood-1k","kind":"see","text":"Webs","sub":"Silver webs strung taut between stakes, each beaded with dew.","acts":[1,2,3],"diff":4},{"id":"wild-wood-1l","kind":"see","text":"Fence sign","sub":"Spelled out in thread across the sign: \"SPIDER'S FIELD\"","acts":[1,2,3],"diff":4},{"id":"wild-wood-1m","kind":"talk","text":"Spider","sub":"A black-and-yellow spider as big as a sheepdog, with a dozen eyes and a pair of tiny spectacles. Fussy, possessive and precise. She talks like a miser.","acts":[1,2,3],"diff":4,"subjects":[{"id":"wild-wood-1n","name":"Sharing","info":"\"But it's mine. The flowers, the grass, the pebbles and the stick, it's all mine.\""},{"id":"wild-wood-1o","name":"Flies","info":"\"I have eaten all the flies around. As a matter of fact, I have been getting hungry.\""}]},{"id":"wild-wood-1p","kind":"interact","text":"Trade the flies.","sub":"Hold the jar out over the fence. She takes it, pays a few sticks and clacks her fangs in satisfaction.","acts":[1,2,3],"diff":4},{"id":"wild-wood-1q","kind":"danger","text":"Steal the sticks.","sub":"She poisons anyone near her field.","acts":[1,2,3],"diff":6},{"id":"wild-wood-1r","kind":"object","text":"Bundle of sticks","sub":"An armful of straight, dry sticks.","acts":[1,2,3],"diff":4},{"id":"wild-wood-1s","kind":"see","text":"Glade path","sub":"Back to the Glade.","acts":[1,2,3],"diff":4}],"desc":"A quiet golden field, fenced in and neatly kept, with webs shining in the sun. The air smells of dry grass and dust."},{"id":"wild-wood-1t","name":"Tunnel","items":[{"id":"wild-wood-1u","kind":"see","text":"Tunnel mouth.","sub":"A hillside arch hung with ivy, with rusted rails running into the dark. A sign over the arch reads MAIN LINE, in flaking paint.","acts":[1,2,3],"diff":4},{"id":"wild-wood-1v","kind":"interact","text":"Main Line","sub":"(Once the Bear has left.) The rails lead down into the Main Line.","acts":[1,2,3],"diff":4},{"id":"wild-wood-1w","kind":"see","text":"Honey pot","sub":"Empty and licked clean, beside him.","acts":[1,2,3],"diff":4},{"id":"wild-wood-1x","kind":"talk","text":"Bear","sub":"A huge brown bear asleep across the rails in a nightcap, snoring so hard that dust falls from the roof. One eye twitches at every sound. Gruff, sleepy and rude. He grumbles at everything.","acts":[1,2,3],"diff":4,"subjects":[{"id":"wild-wood-1y","name":"Sleep","info":"“I’m trying to sleep. Go away.”"},{"id":"wild-wood-1z","name":"Crow","info":"“That racket? A screech. A bird with no ear for music.”"}]},{"id":"wild-wood-20","kind":"interact","text":"Bring the Crow. (Conclusion)","sub":"The Crow perches at the tunnel mouth and sings with his whole heart. The Bear groans, throws off his nightcap and stomps off to find some peace. The Narrator gives the closing line: “And the Bear learned that unkind words have a way of coming home, and he shuffled off to find a quieter place, and had a good long think about what he’d said. The Crow sang on, happy as could be. For kindness given is kindness returned.”","acts":[1,2,3],"diff":4},{"id":"wild-wood-21","kind":"danger","text":"Wake the Bear.","sub":"Will go back to sleep as soon as he is able.","acts":[1,2,3],"diff":8},{"id":"wild-wood-22","kind":"see","text":"Glade path","sub":"Back to the Glade.","acts":[1,2,3],"diff":4}],"desc":"A hillside tunnel mouth, dark and draughty, with ivy hanging over rusted rails. A deep rumbling snore shakes the ground, and a musty animal smell drifts out."},{"id":"wild-wood-23","name":"Edge","items":[{"id":"wild-wood-24","kind":"see","text":"Cliff edge","sub":"A steep drop over a burnt valley, with ash on the wind.","acts":[1,2,3],"diff":4},{"id":"wild-wood-25","kind":"see","text":"Burnt forest","sub":"Blackened trunks and ash drifting like snow, with no birdsong. The ground is gray and brittle.","acts":[1,2,3],"diff":4},{"id":"wild-wood-26","kind":"see","text":"Howler’s Realm","sub":"Far below, a ring of lava around a timber village of longhouses and torches.","acts":[1,2,3],"diff":4},{"id":"wild-wood-27","kind":"talk","text":"Eagle","sub":"A large golden eagle, proud and anxious, circling a ledge with his wings half-folded. Proud, stiff and worried, with a lofty way of speaking.","acts":[1,2,3],"diff":4,"subjects":[{"id":"wild-wood-28","name":"Nest","info":"“Knocked down in the night. My chicks have nothing to sleep in.”"},{"id":"wild-wood-29","name":"Sticks","info":"“Straight ones. A few more would do. The Spider has a field full of them, but she won’t share.”"},{"id":"wild-wood-2a","name":"Howler's Realm","info":"\"A rather violent place, I don't like it much but I can bring you down if you'd like. I just need to finish my nest first.\""}]},{"id":"wild-wood-2b","kind":"see","text":"Ruined nest","sub":"Scattered twigs on a rock ledge, with two fluffy chicks cheeping at the edge of a drop.","acts":[1,2,3],"diff":4},{"id":"wild-wood-2c","kind":"interact","text":"Mend the nest (Conclusion)","sub":"Hand over the sticks. He weaves them in, and the chicks settle. The Narrator gives the sharing moral: “And the Spider learned that a little shared is never a little lost, and the Eagle’s chicks slept safe and sound in their mended nest. For what is shared is doubled.”","acts":[1,2,3],"diff":4},{"id":"wild-wood-2d","kind":"danger","text":"Climb down the cliff.","sub":"A sheer, crumbling drop. No handholds.","acts":[1,2,3],"diff":10},{"id":"wild-wood-2e","kind":"see","text":"Edge path","sub":"Back toward the dead forest.","acts":[1,2,3],"diff":4},{"id":"wild-wood-2f","kind":"see","text":"Glade path","sub":"Back to the Glade.","acts":[1,2,3],"diff":4},{"id":"wild-wood-2g","kind":"interact","text":"Ride the Eagle.","sub":"He carries you down to the Howler’s Realm.","acts":[1,2,3],"diff":4}],"desc":"A cold, windy cliff edge, with a burnt valley far below and a red glow at the bottom. The air smells of ash and sulfur. Wind whistles past the rock, and horns sound faintly from the valley."}],"boons":[{"id":"wild-wood-2h","name":"The Exchequer's Keys","note":"Allows entrance in the Coffer."}],"desc":"A storybook forest of sunlit glades, talking animals and winding paths, narrated by a warm voice that never stops. Underneath the honey and wildflowers, something is rotten.","nightmare":"Omnipotent Third Person","crashDesc":"Wake up in Beaver's dam, nibbled on by Fox, or used as a plush by Bear.","x":40,"y":1940}],"edges":[{"id":"e-breakers-yard-main-line","from":"breakers-yard","to":"main-line","both":true,"locked":true,"label":"Fatberg is blocking the path to the main line. Once unclogged, the train will start again and go to there. It can also be walked, which is a bad idea (check Main Line)"},{"id":"e-breakers-yard-wax-works","from":"breakers-yard","to":"wax-works","both":true,"locked":false,"label":"Open, but crawling with Snuffers."},{"id":"e-district13-rooftop","from":"district13","to":"rooftop","both":true,"locked":false,"label":"Through the fire escape on the courthouse."},{"id":"e-district13-warrens","from":"district13","to":"warrens","both":true,"locked":false,"label":"Through the gate; going out is free, but going in requires a summon, or to be arrested."},{"id":"e-district13-theater","from":"district13","to":"theater","both":true,"locked":true,"label":"The doors are locked during the show."},{"id":"e-district13-big-house","from":"district13","to":"big-house","both":true,"locked":false,"label":"Through the courthouse, although access to the Big House room is prohibited."},{"id":"e-district13-main-line","from":"district13","to":"main-line","both":true,"locked":true,"label":"From the tube entrance, once unclogged."},{"id":"e-howlers-realm-wild-wood","from":"howlers-realm","to":"wild-wood","both":true,"locked":false,"label":"Fly down there on Eagle's back, once he's free."},{"id":"e-rooftop-warrens","from":"rooftop","to":"warrens","both":true,"locked":false,"label":""},{"id":"e-rooftop-bazaar","from":"rooftop","to":"bazaar","both":true,"locked":false,"label":""},{"id":"e-rooftop-highschool","from":"rooftop","to":"highschool","both":true,"locked":false,"label":""},{"id":"e-rooftop-wild-wood","from":"rooftop","to":"wild-wood","both":true,"locked":false,"label":""},{"id":"e-bazaar-warrens","from":"bazaar","to":"warrens","both":true,"locked":false,"label":""},{"id":"e-bazaar-chop-shop","from":"bazaar","to":"chop-shop","both":true,"locked":false,"label":"The shop is open, but the backroom area isn't accessible, Shambles forbids it."},{"id":"e-bazaar-crack-house","from":"bazaar","to":"crack-house","both":true,"locked":false,"label":"From the far landing, getting in and out is fine. But getting through, and to the other landing, is tough because of Fuckwit."},{"id":"e-counting-house-wax-works","from":"counting-house","to":"wax-works","both":true,"locked":false,"label":""},{"id":"e-counting-house-main-line","from":"counting-house","to":"main-line","both":true,"locked":true,"label":""},{"id":"e-crack-house-breakers-yard","from":"crack-house","to":"breakers-yard","both":false,"locked":false,"label":"By falling into the crack. One-way."},{"id":"e-highschool-warrens","from":"highschool","to":"warrens","both":true,"locked":false,"label":""},{"id":"e-highschool-main-line","from":"highschool","to":"main-line","both":true,"locked":true,"label":""},{"id":"e-highschool-playground","from":"highschool","to":"playground","both":true,"locked":true,"label":"Through the gate, once unlocked."},{"id":"e-hoggery-wild-wood","from":"hoggery","to":"wild-wood","both":true,"locked":true,"label":"Through the lake, which can be swam across or rode across in a boat. Unlocked when Beaver dries up the river, making it walkable."},{"id":"e-main-line-wild-wood","from":"main-line","to":"wild-wood","both":true,"locked":true,"label":"If it is opened again, and Bear moved out of it."},{"id":"e-safe-house-wild-wood","from":"safe-house","to":"wild-wood","both":true,"locked":false,"label":"The path between the Wild Wood and the Yard isn't locked, but getting into the Safe House is a different question."},{"id":"e-warrens-wax-works","from":"warrens","to":"wax-works","both":true,"locked":false,"label":""}],"view":{"x":40,"y":20,"k":0.5},"party":{}};
